**Logic**

An anagram has the same length as the pattern, so the window is fixed rather than elastic. Slide it one character at a time, adding the entering character's count and removing the leaving one, and record a match whenever the two frequency profiles agree.

Comparing full count arrays each step would cost O(alphabet) per position. Instead track how many letters currently have the correct count, so a match is the single test `matches == 26`. That gives O(n) overall.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<int> FindAnagrams(string s, string p)
    {
        var result = new List<int>();
        if (string.IsNullOrEmpty(s) || string.IsNullOrEmpty(p) || s.Length < p.Length)
            return result;

        var need = new int[26];
        var window = new int[26];
        foreach (char c in p) need[c - 'a']++;

        // How many of the 26 letters currently have exactly the right count.
        int matches = 0;
        for (int i = 0; i < 26; i++) if (need[i] == 0) matches++;

        for (int i = 0; i < s.Length; i++)
        {
            int entering = s[i] - 'a';
            window[entering]++;
            if (window[entering] == need[entering]) matches++;
            else if (window[entering] == need[entering] + 1) matches--;   // just broke it

            if (i >= p.Length)
            {
                int leaving = s[i - p.Length] - 'a';
                window[leaving]--;
                if (window[leaving] == need[leaving]) matches++;
                else if (window[leaving] == need[leaving] - 1) matches--;
            }

            if (matches == 26) result.Add(i - p.Length + 1);
        }

        return result;
    }

    private static string Show(IList<int> r) => r.Count == 0 ? "(none)" : string.Join(",", r);

    public static void Main()
    {
        Console.WriteLine(Show(FindAnagrams("cbaebabacd", "abc")));
        Console.WriteLine(Show(FindAnagrams("abab", "ab")));
        Console.WriteLine(Show(FindAnagrams("aaaaa", "a")));
        Console.WriteLine(Show(FindAnagrams("ab", "abc")));      // pattern longer
        Console.WriteLine(Show(FindAnagrams("abcd", "xyz")));
        Console.WriteLine(Show(FindAnagrams("baa", "aa")));
    }
}
```

**Output**

```
0,6
0,1,2
0,1,2,3,4
(none)
(none)
1
```

**Logic**

A sliding window with a counter of how many required characters are still missing. Expand the right edge, decrementing the need for each character consumed; when nothing is missing, contract the left edge as far as possible while the window stays valid, recording the best.

The counter is what keeps it linear. Comparing two frequency maps on every step would add an alphabet-sized factor; tracking a single number of satisfied characters makes validity an O(1) test. Each character enters and leaves the window at most once, so O(n + m).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static string MinWindow(string s, string t)
    {
        if (string.IsNullOrEmpty(s) || string.IsNullOrEmpty(t) || s.Length < t.Length)
            return "";

        var need = new Dictionary<char, int>();
        foreach (char c in t) need[c] = need.TryGetValue(c, out int n) ? n + 1 : 1;

        int missing = t.Length;          // total characters still owed, counting duplicates
        int bestStart = 0, bestLength = int.MaxValue;
        int left = 0;

        for (int right = 0; right < s.Length; right++)
        {
            char c = s[right];

            // Only a character we still owe reduces the deficit.
            if (need.TryGetValue(c, out int owed))
            {
                if (owed > 0) missing--;
                need[c] = owed - 1;      // may go negative: a surplus copy
            }

            while (missing == 0)         // valid: try to shrink from the left
            {
                if (right - left + 1 < bestLength)
                {
                    bestLength = right - left + 1;
                    bestStart = left;
                }

                char leaving = s[left++];
                if (need.TryGetValue(leaving, out int have))
                {
                    need[leaving] = have + 1;
                    if (have + 1 > 0) missing++;   // only a needed copy breaks validity
                }
            }
        }

        return bestLength == int.MaxValue ? "" : s.Substring(bestStart, bestLength);
    }

    private static string Show(string s) => s.Length == 0 ? "(none)" : s;

    public static void Main()
    {
        Console.WriteLine(Show(MinWindow("ADOBECODEBANC", "ABC")));
        Console.WriteLine(Show(MinWindow("a", "a")));
        Console.WriteLine(Show(MinWindow("a", "aa")));       // not enough copies
        Console.WriteLine(Show(MinWindow("ab", "b")));
        Console.WriteLine(Show(MinWindow("aaflslflsldkalskaaa", "aaa")));
        Console.WriteLine(Show(MinWindow("abc", "")));
    }
}
```

