a
(none)
b
aaa
(none)
```

**Logic**

The straightforward approach tries every alignment: for each starting position in the haystack, compare characters until a mismatch. That is O(n·m) in the worst case, for example searching `"aaab"` in a long run of `"a"`s, though it is close to O(n) on typical text.

KMP brings it to O(n + m) by precomputing, for each prefix of the needle, the length of the longest proper prefix that is also a suffix. On a mismatch, that table says how far the needle can shift without re-examining characters already matched, so the haystack pointer never moves backwards.

**Program**

```csharp
using System;

public class Solution
{
    // Naive: simple, and genuinely fine for short needles.
    public static int StrStr(string haystack, string needle)
    {
        if (string.IsNullOrEmpty(needle)) return 0;
        if (haystack == null || needle.Length > haystack.Length) return -1;

        for (int start = 0; start <= haystack.Length - needle.Length; start++)
        {
            int k = 0;
            while (k < needle.Length && haystack[start + k] == needle[k]) k++;
            if (k == needle.Length) return start;
        }
        return -1;
    }

    // KMP: O(n + m), no backtracking in the haystack.
    public static int StrStrKmp(string haystack, string needle)
    {
        if (string.IsNullOrEmpty(needle)) return 0;
        if (haystack == null || needle.Length > haystack.Length) return -1;

        int[] lps = BuildLps(needle);
        int i = 0, j = 0;

        while (i < haystack.Length)
        {
            if (haystack[i] == needle[j])
            {
                i++; j++;
                if (j == needle.Length) return i - j;
            }
            else if (j > 0) j = lps[j - 1];   // shift the needle, keep i put
            else i++;
        }
        return -1;
    }

    // lps[k] = length of the longest proper prefix of needle[0..k] that is also its suffix.
    private static int[] BuildLps(string needle)
    {
        var lps = new int[needle.Length];
        int length = 0;

        for (int i = 1; i < needle.Length; )
        {
            if (needle[i] == needle[length]) lps[i++] = ++length;
            else if (length > 0) length = lps[length - 1];
            else lps[i++] = 0;
        }
        return lps;
    }

    public static void Main()
    {
        Console.WriteLine(StrStr("sadbutsad", "sad"));
        Console.WriteLine(StrStrKmp("sadbutsad", "sad"));
        Console.WriteLine(StrStr("leetcode", "leeto"));
        Console.WriteLine(StrStrKmp("aaaaab", "aab"));      // the naive worst case
        Console.WriteLine(StrStr("abc", ""));               // empty needle
        Console.WriteLine(StrStrKmp("a", "aa"));            // needle longer
        Console.WriteLine(string.Join(",", BuildLps("aabaaac")));
    }
}
```

