**Logic**

The requirement is usually to reverse the word order while leaving each word intact, and to normalise whitespace: no leading or trailing spaces, and exactly one space between words.

Scanning from the end and collecting each word is a single pass, O(n) time. The classic in-place variant for a character array is the same three-reversal trick as array rotation: reverse the entire string, then reverse each word back to the correct order.

**Program**

```csharp
using System;
using System.Text;

public class Solution
{
    // One pass from the right, emitting whole words as they are found.
    public static string ReverseWords(string s)
    {
        if (string.IsNullOrWhiteSpace(s)) return "";

        var sb = new StringBuilder(s.Length);
        int i = s.Length - 1;

        while (i >= 0)
        {
            while (i >= 0 && s[i] == ' ') i--;               // skip trailing/extra spaces
            if (i < 0) break;

            int end = i;
            while (i >= 0 && s[i] != ' ') i--;               // walk to the word's start

            if (sb.Length > 0) sb.Append(' ');               // single separator
            sb.Append(s, i + 1, end - i);
        }

        return sb.ToString();
    }

    // In-place on a char array: reverse everything, then reverse each word back.
    public static string ReverseWordsInPlace(char[] chars)
    {
        Reverse(chars, 0, chars.Length - 1);

        int start = 0;
        for (int i = 0; i <= chars.Length; i++)
        {
            if (i == chars.Length || chars[i] == ' ')
            {
                Reverse(chars, start, i - 1);
                start = i + 1;
            }
        }
        return new string(chars);
    }

    private static void Reverse(char[] c, int i, int j)
    {
        while (i < j) { (c[i], c[j]) = (c[j], c[i]); i++; j--; }
    }

    public static void Main()
    {
        Console.WriteLine($"[{ReverseWords("the sky is blue")}]");
        Console.WriteLine($"[{ReverseWords("  hello world  ")}]");        // trimmed
        Console.WriteLine($"[{ReverseWords("a good   example")}]");       // collapsed
        Console.WriteLine($"[{ReverseWords("single")}]");
        Console.WriteLine($"[{ReverseWords("   ")}]");                    // only spaces
        Console.WriteLine($"[{ReverseWordsInPlace("the sky is blue".ToCharArray())}]");
    }
}
```

