```

**Logic**

Take the first string as a working prefix and shorten it against each subsequent string until it matches as a prefix. Equivalently, and more simply, compare column by column: check character position 0 across all strings, then position 1, and stop at the first mismatch or when any string ends.

O(S) where S is the total number of characters, since in the worst case every character of every string is examined once. O(1) extra space.

**Program**

```csharp
using System;

public class Solution
{
    public static string LongestCommonPrefix(string[] strs)
    {
        if (strs == null || strs.Length == 0) return "";

        // Vertical scan: position by position across every string.
        for (int pos = 0; pos < strs[0].Length; pos++)
        {
            char c = strs[0][pos];

            for (int s = 1; s < strs.Length; s++)
                if (pos >= strs[s].Length || strs[s][pos] != c)
                    return strs[0].Substring(0, pos);   // first divergence
        }

        return strs[0];    // the first string is itself the common prefix
    }

    // Horizontal scan: shrink a running prefix. Same complexity, different shape.
    public static string LongestCommonPrefixHorizontal(string[] strs)
    {
        if (strs == null || strs.Length == 0) return "";

        string prefix = strs[0];
        foreach (string s in strs)
        {
            while (!s.StartsWith(prefix, StringComparison.Ordinal))
            {
                prefix = prefix.Substring(0, prefix.Length - 1);
                if (prefix.Length == 0) return "";
            }
        }
        return prefix;
    }

    private static string Show(string s) => s.Length == 0 ? "(empty)" : s;

    public static void Main()
    {
        Console.WriteLine(Show(LongestCommonPrefix(new[] { "flower", "flow", "flight" })));
        Console.WriteLine(Show(LongestCommonPrefix(new[] { "dog", "racecar", "car" })));
        Console.WriteLine(Show(LongestCommonPrefix(new[] { "interspecies", "interstellar", "interstate" })));
        Console.WriteLine(Show(LongestCommonPrefix(new[] { "alone" })));
        Console.WriteLine(Show(LongestCommonPrefix(new[] { "", "abc" })));        // empty string wins
        Console.WriteLine(Show(LongestCommonPrefixHorizontal(new[] { "ab", "a" })));
    }
}
```

