1
1
4
```

**Logic**

Add each element to a hash set; the first time an add fails, a duplicate exists. `HashSet<T>.Add` returns false when the item is already present, so one call does both the lookup and the insert. O(n) time, O(n) space, and it returns early rather than always scanning the whole array.

Sorting first and comparing neighbours is O(n log n) time with O(1) extra space if sorting in place is allowed, which is the better answer when memory is the binding constraint or when the caller does not mind the input being reordered.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static bool ContainsDuplicate(int[] nums)
    {
        if (nums == null || nums.Length < 2) return false;

        var seen = new HashSet<int>(nums.Length);   // presized: no rehashing

        foreach (int n in nums)
            if (!seen.Add(n)) return true;          // Add is false when already present

        return false;
    }

    // O(1) extra space, at the cost of reordering the caller's array.
    public static bool ContainsDuplicateSorted(int[] nums)
    {
        if (nums == null || nums.Length < 2) return false;
        Array.Sort(nums);
        for (int i = 1; i < nums.Length; i++)
            if (nums[i] == nums[i - 1]) return true;
        return false;
    }

    public static void Main()
    {
        Console.WriteLine(ContainsDuplicate(new[] { 1, 2, 3, 1 }));
        Console.WriteLine(ContainsDuplicate(new[] { 1, 2, 3, 4 }));
        Console.WriteLine(ContainsDuplicate(new[] { 1, 1, 1, 3, 3, 4, 3, 2, 4, 2 }));
        Console.WriteLine(ContainsDuplicate(new int[0]));
        Console.WriteLine(ContainsDuplicateSorted(new[] { 5, 3, 5 }));
    }
}
```

