**Logic**

Sort by start time, then sweep. Keep the current interval; if the next one starts at or before the current end, they overlap, so extend the end to the larger of the two; otherwise close the current interval and start a new one. O(n log n) dominated by the sort, O(n) output.

For inserting into an already-sorted list, the sort is unnecessary and it becomes three linear phases: intervals entirely before the new one, intervals overlapping it (absorbed by widening), and intervals entirely after. That is O(n).

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int[][] Merge(int[][] intervals)
    {
        if (intervals == null || intervals.Length == 0) return Array.Empty<int[]>();

        var sorted = intervals.OrderBy(i => i[0]).ToArray();
        var merged = new List<int[]>();
        var current = new[] { sorted[0][0], sorted[0][1] };

        foreach (var next in sorted.Skip(1))
        {
            if (next[0] <= current[1])                       // touching counts as overlapping
                current[1] = Math.Max(current[1], next[1]);  // max, not next[1]: nesting
            else
            {
                merged.Add(current);
                current = new[] { next[0], next[1] };
            }
        }

        merged.Add(current);
        return merged.ToArray();
    }

    // Already sorted and non-overlapping: insert in O(n), no sort needed.
    public static int[][] Insert(int[][] intervals, int[] newInterval)
    {
        var result = new List<int[]>();
        int i = 0, n = intervals.Length;
        int start = newInterval[0], end = newInterval[1];

        while (i < n && intervals[i][1] < start) result.Add(intervals[i++]);      // strictly before

        while (i < n && intervals[i][0] <= end)                                   // overlapping
        {
            start = Math.Min(start, intervals[i][0]);
            end = Math.Max(end, intervals[i][1]);
            i++;
        }
        result.Add(new[] { start, end });

        while (i < n) result.Add(intervals[i++]);                                 // strictly after
        return result.ToArray();
    }

    private static string Render(int[][] r) =>
        r.Length == 0 ? "(none)" : string.Join(" ", r.Select(x => $"[{x[0]},{x[1]}]"));

    public static void Main()
    {
        Console.WriteLine(Render(Merge(new[] {
            new[] { 1, 3 }, new[] { 2, 6 }, new[] { 8, 10 }, new[] { 15, 18 } })));

        Console.WriteLine(Render(Merge(new[] { new[] { 1, 4 }, new[] { 4, 5 } })));   // touching
        Console.WriteLine(Render(Merge(new[] { new[] { 1, 10 }, new[] { 2, 3 } })));  // nested
        Console.WriteLine(Render(Merge(new[] { new[] { 5, 6 }, new[] { 1, 2 } })));   // unsorted input

        Console.WriteLine(Render(Insert(new[] {
            new[] { 1, 3 }, new[] { 6, 9 } }, new[] { 2, 5 })));

        Console.WriteLine(Render(Insert(Array.Empty<int[]>(), new[] { 4, 8 })));
    }
}
```

