**Logic**

Removing the fewest intervals is the same as keeping the most, which is the classic activity-selection problem. Sort by *end* time and greedily keep each interval whose start is at or after the last kept end.

Sorting by end is the crucial choice: the interval that finishes earliest leaves the most room for everything after it. Sorting by start fails, because one very long interval starting early would be kept and block many short ones.

O(n log n) for the sort, then one linear pass.

**Program**

```csharp
using System;
using System.Linq;

public class Solution
{
    public static int EraseOverlapIntervals(int[][] intervals)
    {
        if (intervals == null || intervals.Length == 0) return 0;

        // Sort by END: the earliest finisher leaves the most room afterwards.
        var sorted = intervals.OrderBy(i => i[1]).ToArray();

        int kept = 1;
        int lastEnd = sorted[0][1];

        for (int i = 1; i < sorted.Length; i++)
        {
            if (sorted[i][0] >= lastEnd)   // touching is not overlapping
            {
                kept++;
                lastEnd = sorted[i][1];
            }
        }

        return intervals.Length - kept;
    }

    public static void Main()
    {
        Console.WriteLine(EraseOverlapIntervals(new[] {
            new[] { 1, 2 }, new[] { 2, 3 }, new[] { 3, 4 }, new[] { 1, 3 } }));

        Console.WriteLine(EraseOverlapIntervals(new[] {
            new[] { 1, 2 }, new[] { 1, 2 }, new[] { 1, 2 } }));

        Console.WriteLine(EraseOverlapIntervals(new[] {
            new[] { 1, 2 }, new[] { 2, 3 } }));        // touching: keep both

        Console.WriteLine(EraseOverlapIntervals(new[] { new[] { 1, 100 } }));

        // One long interval versus three short ones: sorting by start would fail.
        Console.WriteLine(EraseOverlapIntervals(new[] {
            new[] { 0, 10 }, new[] { 1, 2 }, new[] { 3, 4 }, new[] { 5, 6 } }));

        Console.WriteLine(EraseOverlapIntervals(Array.Empty<int[]>()));
    }
}
```

**Output**

```
1
2
0
0
1
0
```

**Logic**

The answer is the maximum number of meetings running at the same time. Treat starts and ends as events on a timeline: a start needs a room, an end frees one. Sort both arrays independently, then sweep with two pointers, incrementing a counter on each start and decrementing when the next end has already passed. The peak of that counter is the answer. O(n log n) for the sorts, O(n) space.

The min-heap formulation is equivalent: keep the end times of occupied rooms and reuse the earliest-finishing room whenever the next meeting starts after it.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    // Two sorted arrays of events. Sorting starts and ends independently is
    // legitimate: the pairing does not matter, only how many are active.
    public static int MinMeetingRooms(int[][] intervals)
    {
        if (intervals == null || intervals.Length == 0) return 0;

        var starts = intervals.Select(i => i[0]).OrderBy(x => x).ToArray();
        var ends = intervals.Select(i => i[1]).OrderBy(x => x).ToArray();

        int rooms = 0, peak = 0, e = 0;

        foreach (int start in starts)
        {
            // Free every room whose meeting finished at or before this start.
            while (e < ends.Length && ends[e] <= start) { rooms--; e++; }

            rooms++;
            if (rooms > peak) peak = rooms;
        }

        return peak;
    }

    // Min-heap of end times: the root is the room that frees up soonest.
    public static int MinMeetingRoomsHeap(int[][] intervals)
    {
        if (intervals == null || intervals.Length == 0) return 0;

        var sorted = intervals.OrderBy(i => i[0]).ToArray();
        var rooms = new PriorityQueue<int, int>();      // end times

        foreach (var meeting in sorted)
        {
            if (rooms.Count > 0 && rooms.Peek() <= meeting[0])
                rooms.Dequeue();                        // reuse that room

            rooms.Enqueue(meeting[1], meeting[1]);
        }

        return rooms.Count;
    }

    public static void Main()
    {
        var a = new[] { new[] { 0, 30 }, new[] { 5, 10 }, new[] { 15, 20 } };
        Console.WriteLine(MinMeetingRooms(a));
        Console.WriteLine(MinMeetingRoomsHeap(a));

