        Console.WriteLine(MinMeetingRooms(new[] { new[] { 1, 5 }, new[] { 2, 6 }, new[] { 3, 7 } }));
        Console.WriteLine(MinMeetingRooms(Array.Empty<int[]>()));
    }
}
