**Logic**

A min-heap of size k. Push elements while the heap is smaller than k; after that, if an element is larger than the heap's smallest, replace it. The heap ends up holding the k largest elements, and its root is the kth largest. O(n log k) time, O(k) space.

Quickselect is the other answer: partition as in quicksort but recurse only into the side containing the target rank, giving O(n) average time and O(1) extra space, though O(n²) in the worst case. The heap is preferred when the data is a stream or k is much smaller than n.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    // Min-heap of size k: O(n log k), and works on a stream.
    public static int FindKthLargestHeap(int[] nums, int k)
    {
        var heap = new PriorityQueue<int, int>();   // min-heap by priority

        foreach (int n in nums)
        {
            heap.Enqueue(n, n);
            if (heap.Count > k) heap.Dequeue();      // drop the smallest
        }

        return heap.Peek();
    }

    // Quickselect: O(n) average, in place, but needs the whole array up front.
    public static int FindKthLargestQuickselect(int[] nums, int k)
    {
        int target = nums.Length - k;               // kth largest = this index when sorted
        int low = 0, high = nums.Length - 1;
        var rng = new Random(42);                   // fixed seed: reproducible output

        while (true)
        {
            if (low == high) return nums[low];

            // Random pivot: guards against the sorted-input worst case.
            int pivotIndex = low + rng.Next(high - low + 1);
            pivotIndex = Partition(nums, low, high, pivotIndex);

            if (pivotIndex == target) return nums[pivotIndex];
            if (pivotIndex < target) low = pivotIndex + 1;
            else high = pivotIndex - 1;
        }
    }

    private static int Partition(int[] nums, int low, int high, int pivotIndex)
    {
        int pivot = nums[pivotIndex];
        (nums[pivotIndex], nums[high]) = (nums[high], nums[pivotIndex]);   // park the pivot

        int store = low;
        for (int i = low; i < high; i++)
            if (nums[i] < pivot)
                (nums[store], nums[i]) = (nums[i], nums[store++]);

        (nums[high], nums[store]) = (nums[store], nums[high]);             // pivot to its place
        return store;
    }

    public static void Main()
    {
        Console.WriteLine(FindKthLargestHeap(new[] { 3, 2, 1, 5, 6, 4 }, 2));
        Console.WriteLine(FindKthLargestQuickselect(new[] { 3, 2, 1, 5, 6, 4 }, 2));

        Console.WriteLine(FindKthLargestHeap(new[] { 3, 2, 3, 1, 2, 4, 5, 5, 6 }, 4));
        Console.WriteLine(FindKthLargestQuickselect(new[] { 3, 2, 3, 1, 2, 4, 5, 5, 6 }, 4));

        Console.WriteLine(FindKthLargestHeap(new[] { 1 }, 1));
        Console.WriteLine(FindKthLargestHeap(new[] { 7, 7, 7 }, 2));   // duplicates count separately
    }
}
```

