**Logic**

Count frequencies with a dictionary, then select the k highest counts. The selection can be a min-heap of size k, giving O(n log k), or bucket sort, giving O(n).

Bucket sort wins here because of a bound the problem hands you: no frequency can exceed n. So make n+1 buckets indexed by frequency, drop each value into its bucket, and read buckets from the top down until k values are collected. That is O(n) time and O(n) space, and it beats the heap.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    // O(n) via bucket sort on frequency, which cannot exceed n.
    public static int[] TopKFrequent(int[] nums, int k)
    {
        var counts = new Dictionary<int, int>();
        foreach (int n in nums)
            counts[n] = counts.TryGetValue(n, out int c) ? c + 1 : 1;

        // buckets[f] holds every value occurring exactly f times.
        var buckets = new List<int>[nums.Length + 1];
        foreach (var (value, count) in counts)
            (buckets[count] ??= new List<int>()).Add(value);

        var result = new List<int>(k);
        for (int f = buckets.Length - 1; f >= 1 && result.Count < k; f--)
        {
            if (buckets[f] == null) continue;
            foreach (int v in buckets[f])
            {
                result.Add(v);
                if (result.Count == k) break;
            }
        }

        return result.ToArray();
    }

    // O(n log k) with a bounded min-heap: better when k is tiny and n is huge,
    // and the only option when the input is a stream.
    public static int[] TopKFrequentHeap(int[] nums, int k)
    {
        var counts = new Dictionary<int, int>();
        foreach (int n in nums)
            counts[n] = counts.TryGetValue(n, out int c) ? c + 1 : 1;

        var heap = new PriorityQueue<int, int>();
        foreach (var (value, count) in counts)
        {
            heap.Enqueue(value, count);
            if (heap.Count > k) heap.Dequeue();     // evict the least frequent
        }

        var result = new List<int>();
        while (heap.Count > 0) result.Add(heap.Dequeue());
        result.Reverse();                          // heap pops ascending
        return result.ToArray();
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(",", TopKFrequent(new[] { 1, 1, 1, 2, 2, 3 }, 2)));
        Console.WriteLine(string.Join(",", TopKFrequentHeap(new[] { 1, 1, 1, 2, 2, 3 }, 2)));
        Console.WriteLine(string.Join(",", TopKFrequent(new[] { 1 }, 1)));
        Console.WriteLine(string.Join(",", TopKFrequent(new[] { 4, 4, 5, 5, 6 }, 3)));
        Console.WriteLine(string.Join(",", TopKFrequent(new[] { 7, 7, 7 }, 1)));
    }
}
```

