**Logic**

A monotonic deque holding indices whose values decrease from front to back. Before adding a new index, pop from the back every index whose value is smaller, because a smaller value with a later index can never again be the maximum. Pop from the front any index that has slid out of the window. The front is then always the current maximum.

Each index is pushed and popped at most once, so O(n) overall, against O(n·k) for rescanning each window and O(n log n) for a heap.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int[] MaxSlidingWindow(int[] nums, int k)
    {
        if (nums == null || nums.Length == 0 || k <= 0) return Array.Empty<int>();
        if (k == 1) return nums;

        var deque = new LinkedList<int>();     // indices, values decreasing front to back
        var result = new int[nums.Length - k + 1];

        for (int i = 0; i < nums.Length; i++)
        {
            // Drop indices that have fallen out of the window.
            if (deque.Count > 0 && deque.First.Value <= i - k) deque.RemoveFirst();

            // A smaller earlier value can never be the max while this one is in range.
            while (deque.Count > 0 && nums[deque.Last.Value] <= nums[i]) deque.RemoveLast();

            deque.AddLast(i);

            if (i >= k - 1) result[i - k + 1] = nums[deque.First.Value];
        }

        return result;
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(",", MaxSlidingWindow(new[] { 1, 3, -1, -3, 5, 3, 6, 7 }, 3)));
        Console.WriteLine(string.Join(",", MaxSlidingWindow(new[] { 1 }, 1)));
        Console.WriteLine(string.Join(",", MaxSlidingWindow(new[] { 9, 8, 7, 6 }, 2)));  // decreasing
        Console.WriteLine(string.Join(",", MaxSlidingWindow(new[] { 1, 2, 3, 4 }, 2)));  // increasing
        Console.WriteLine(string.Join(",", MaxSlidingWindow(new[] { 7, 7, 7 }, 2)));     // duplicates
        Console.WriteLine(string.Join(",", MaxSlidingWindow(new[] { 4, 2, 12 }, 3)));
    }
}
