**Logic**

Scan from the right for the first position whose value is smaller than its successor; call it the pivot. Everything to its right is non-increasing, so it is already the largest arrangement of those elements and cannot be advanced.

Then find, again from the right, the smallest element greater than the pivot, swap them, and reverse the suffix. Reversing turns the suffix from its largest arrangement into its smallest, giving the immediate next permutation rather than some later one.

If no pivot exists the whole array is descending, so the next permutation wraps to the fully ascending one, achieved by reversing everything. O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static void NextPermutation(int[] nums)
    {
        int n = nums.Length;
        if (n < 2) return;

        // 1. Rightmost position with a smaller value than its successor.
        int pivot = n - 2;
        while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) pivot--;

        if (pivot >= 0)
        {
            // 2. Rightmost element greater than the pivot. The suffix is
            //    non-increasing, so the first one found from the right is the
            //    smallest such element.
            int swap = n - 1;
            while (nums[swap] <= nums[pivot]) swap--;

            (nums[pivot], nums[swap]) = (nums[swap], nums[pivot]);
        }

        // 3. The suffix is still non-increasing; reverse it to its smallest form.
        Array.Reverse(nums, pivot + 1, n - pivot - 1);
    }

    private static string Next(params int[] nums)
    {
        NextPermutation(nums);
        return string.Join(",", nums);
    }

    public static void Main()
    {
        Console.WriteLine(Next(1, 2, 3));
        Console.WriteLine(Next(3, 2, 1));      // last permutation wraps to the first
        Console.WriteLine(Next(1, 1, 5));
        Console.WriteLine(Next(1, 3, 2));
        Console.WriteLine(Next(2, 3, 1));
        Console.WriteLine(Next(1));
    }
}
