**Logic**

Three pointers partitioning the array into four regions: settled 0s at the front, settled 1s next, an unexamined middle, and settled 2s at the back. `low` marks the end of the 0s, `high` marks the start of the 2s, and `mid` scans.

On a 0, swap it to `low` and advance both `low` and `mid`. On a 1, just advance `mid`. On a 2, swap it to `high` and decrement `high` but **do not** advance `mid`, because the value swapped in from the back has not been examined yet. That asymmetry is the crux. O(n) time, O(1) space, one pass.

**Program**

```csharp
using System;

public class Solution
{
    public static void SortColors(int[] nums)
    {
        int low = 0, mid = 0, high = nums.Length - 1;

        while (mid <= high)
        {
            switch (nums[mid])
            {
                case 0:
                    (nums[low], nums[mid]) = (nums[mid], nums[low]);
                    low++;
                    mid++;      // the value swapped in came from below mid: already seen
                    break;

                case 1:
                    mid++;      // already in the right region
                    break;

                default:        // 2
                    (nums[mid], nums[high]) = (nums[high], nums[mid]);
                    high--;
                    // mid is NOT advanced: the incoming value is unexamined
                    break;
            }
        }
    }

    private static string Sorted(int[] a)
    {
        var copy = (int[])a.Clone();
        SortColors(copy);
        return string.Join(",", copy);
    }

    public static void Main()
    {
        Console.WriteLine(Sorted(new[] { 2, 0, 2, 1, 1, 0 }));
        Console.WriteLine(Sorted(new[] { 2, 0, 1 }));
        Console.WriteLine(Sorted(new[] { 0 }));
        Console.WriteLine(Sorted(new[] { 2, 2, 2 }));
        Console.WriteLine(Sorted(new[] { 1, 0 }));
        Console.WriteLine(Sorted(new[] { 2, 1, 0, 2, 1, 0 }));
    }
}
```

