**Logic**

Backtracking over cut positions. From the current index, try every prefix; when a prefix is a palindrome, take it as one part and recurse on the remainder. When the index reaches the end, the accumulated parts form a complete partition.

The useful optimisation is to precompute palindromic status for every substring with an O(n²) DP, so the palindrome test inside the recursion is a single lookup rather than an O(n) scan. That matters because the same substrings are tested repeatedly across branches.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static IList<IList<string>> Partition(string s)
    {
        var result = new List<IList<string>>();
        if (string.IsNullOrEmpty(s)) return result;

        // isPalindrome[i,j] for the substring from i to j inclusive.
        var isPalindrome = new bool[s.Length, s.Length];
        for (int end = 0; end < s.Length; end++)
            for (int start = end; start >= 0; start--)
                isPalindrome[start, end] = s[start] == s[end]
                    && (end - start < 2 || isPalindrome[start + 1, end - 1]);

        Backtrack(s, 0, isPalindrome, new List<string>(), result);
        return result;
    }

    private static void Backtrack(string s, int start, bool[,] isPalindrome,
                                  List<string> current, IList<IList<string>> result)
    {
        if (start == s.Length)
        {
            result.Add(new List<string>(current));
            return;
        }

        for (int end = start; end < s.Length; end++)
        {
            if (!isPalindrome[start, end]) continue;   // O(1) lookup, not a rescan

            current.Add(s[start..(end + 1)]);
            Backtrack(s, end + 1, isPalindrome, current, result);
            current.RemoveAt(current.Count - 1);
        }
    }

    private static string Render(IList<IList<string>> r) =>
        r.Count == 0 ? "(none)" : string.Join(" ", r.Select(p => "[" + string.Join(",", p) + "]"));

    public static void Main()
    {
        Console.WriteLine(Render(Partition("aab")));
        Console.WriteLine(Render(Partition("a")));
        Console.WriteLine(Render(Partition("ab")));
        Console.WriteLine(Render(Partition("aaa")));
        Console.WriteLine(Partition("aaaa").Count);
    }
}
```

**Output**

```
[a,a,b] [aa,b]
[a]
[a,b]
[a,a,a] [a,aa] [aa,a] [aaa]
8
```

Every single character is a palindrome, so a partition always exists — `ab` splits into `[a,b]` rather than returning nothing.

**Logic**

Two observations make this linear. If the total gas is at least the total cost, a solution exists and is unique; otherwise none does. And if the running tank goes negative somewhere between a candidate start and station i, then no station in that span can be a valid start either, because each would begin with at most as much fuel.

So one pass suffices: track the total surplus to decide feasibility, and a running tank that resets the candidate start to the next station whenever it dips below zero.

O(n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int CanCompleteCircuit(int[] gas, int[] cost)
    {
        if (gas == null || cost == null || gas.Length != cost.Length) return -1;

        int totalSurplus = 0;   // decides whether ANY start works
        int tank = 0;           // fuel since the current candidate start
        int start = 0;

        for (int i = 0; i < gas.Length; i++)
        {
            int surplus = gas[i] - cost[i];
            totalSurplus += surplus;
            tank += surplus;

            if (tank < 0)
            {
                // Nothing from start..i can work, so try the next station.
                start = i + 1;
                tank = 0;
            }
        }

        return totalSurplus >= 0 ? start : -1;
    }

    public static void Main()
    {
        Console.WriteLine(CanCompleteCircuit(
            new[] { 1, 2, 3, 4, 5 }, new[] { 3, 4, 5, 1, 2 }));

        Console.WriteLine(CanCompleteCircuit(
            new[] { 2, 3, 4 }, new[] { 3, 4, 3 }));        // impossible

        Console.WriteLine(CanCompleteCircuit(new[] { 5 }, new[] { 4 }));
        Console.WriteLine(CanCompleteCircuit(new[] { 3 }, new[] { 4 }));
        Console.WriteLine(CanCompleteCircuit(new[] { 1, 2 }, new[] { 2, 1 }));
        Console.WriteLine(CanCompleteCircuit(new[] { 4, 5, 2, 6, 5, 3 },
                                            new[] { 3, 2, 7, 3, 2, 9 }));
    }
}
```

