-1
0
-1
1
-1
```

**Logic**

The answer must lie between 1 and n+1, because n numbers cannot cover more than n distinct positive values. So the array itself can serve as the lookup table: place each value v in the range 1..n at index v-1, then scan for the first position whose value does not match.

The placement uses a while loop with swapping, not a single pass, because a swap brings in a new value that may also be misplaced. Each successful swap puts one number permanently in its home, so the total work is O(n) despite the nested loop.

**Program**

```csharp
using System;

public class Solution
{
    public static int FirstMissingPositive(int[] nums)
    {
        if (nums == null || nums.Length == 0) return 1;

        int n = nums.Length;

        // Cyclic sort: put value v at index v-1, for every v in 1..n.
        for (int i = 0; i < n; i++)
        {
            // while, not if: the incoming value may also belong elsewhere.
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i])
                (nums[nums[i] - 1], nums[i]) = (nums[i], nums[nums[i] - 1]);
        }

        for (int i = 0; i < n; i++)
            if (nums[i] != i + 1) return i + 1;

        return n + 1;       // 1..n all present
    }

    private static int Missing(params int[] nums) => FirstMissingPositive(nums);

    public static void Main()
    {
        Console.WriteLine(Missing(1, 2, 0));
        Console.WriteLine(Missing(3, 4, -1, 1));
        Console.WriteLine(Missing(7, 8, 9, 11, 12));   // nothing in range
        Console.WriteLine(Missing(1, 2, 3));           // all present
        Console.WriteLine(Missing(1, 1));              // duplicates
        Console.WriteLine(Missing(-5));
    }
}
