**Logic**

`reachable[i]` means the first i characters can be split into dictionary words. It is true when some earlier position j is reachable and the slice from j to i is a word. Position 0 is reachable as the empty prefix.

O(n²) substring checks against a hash set of words, so O(n²·L) overall with string comparison. The naive recursion without memoisation is exponential, which is the point of the exercise: strings like "aaaaaaab" over a dictionary of "a", "aa", "aaa" blow up.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static bool WordBreak(string s, IList<string> wordDict)
    {
        if (string.IsNullOrEmpty(s)) return true;

        var words = new HashSet<string>(wordDict);
        int longest = 0;
        foreach (string w in words) longest = Math.Max(longest, w.Length);

        var reachable = new bool[s.Length + 1];
        reachable[0] = true;            // the empty prefix is trivially reachable

        for (int i = 1; i <= s.Length; i++)
        {
            // Only look back as far as the longest dictionary word.
            for (int j = Math.Max(0, i - longest); j < i; j++)
            {
                if (!reachable[j]) continue;

                if (words.Contains(s[j..i]))
                {
                    reachable[i] = true;
                    break;
                }
            }
        }

        return reachable[s.Length];
    }

    public static void Main()
    {
        Console.WriteLine(WordBreak("leetcode", new List<string> { "leet", "code" }));
        Console.WriteLine(WordBreak("applepenapple", new List<string> { "apple", "pen" }));
        Console.WriteLine(WordBreak("catsandog",
            new List<string> { "cats", "dog", "sand", "and", "cat" }));
        Console.WriteLine(WordBreak("", new List<string> { "a" }));
        Console.WriteLine(WordBreak("a", new List<string>()));
        Console.WriteLine(WordBreak("aaaaaaa", new List<string> { "aaa", "aaaa" }));
    }
}
```

