2
-1
0
-1
-1
```

**Logic**

Walk the list carrying three references: the node before, the node now, and the node after. On each step, point the current node's `next` backwards, then shift all three forward one position. Capturing `next` before overwriting it is the whole trick, because without it the rest of the list is unreachable. One pass, O(n) time, O(1) space.

The recursive version reads more elegantly but uses O(n) stack, which on a long list is a real stack-overflow risk, so the iterative form is the one to lead with.

**Program**

```csharp
using System;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode Reverse(ListNode head)
    {
        ListNode prev = null;
        ListNode current = head;

        while (current != null)
        {
            ListNode next = current.Next;  // save it before the link is destroyed
            current.Next = prev;           // flip the pointer backwards
            prev = current;                // advance both markers
            current = next;
        }

        return prev;   // current is null here, so prev is the old tail = new head
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode head)
    {
        var parts = new System.Collections.Generic.List<string>();
        for (var n = head; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join(" -> ", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(Reverse(Build(1, 2, 3, 4, 5))));
        Console.WriteLine(Render(Reverse(Build(1, 2))));
        Console.WriteLine(Render(Reverse(Build(7))));
        Console.WriteLine(Render(Reverse(null)));
    }
}
```

**Output**

```
5 -> 4 -> 3 -> 2 -> 1
2 -> 1
7
(empty)
```

**Logic**

Floyd's tortoise and hare. Move one pointer one node at a time and another two nodes at a time. If the list ends, the fast pointer reaches null and there is no cycle. If there is a cycle, both pointers are eventually trapped inside it and the fast one gains exactly one position per step on the slow one, so it must land on it rather than step over it. O(n) time, O(1) space.

The obvious alternative, a hash set of visited nodes, is also O(n) time but O(n) space. Floyd's is preferred because it allocates nothing, and it extends to finding where the cycle begins.

**Program**

```csharp
using System;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0) { Val = val; }
}

public class Solution
{
    public static bool HasCycle(ListNode head)
    {
        ListNode slow = head, fast = head;

        while (fast != null && fast.Next != null)
        {
            slow = slow.Next;        // one step
            fast = fast.Next.Next;   // two steps
            if (ReferenceEquals(slow, fast)) return true;
        }

        return false;   // fast ran off the end, so the list terminates
    }

    // Where does the cycle start? Reset one pointer to the head and advance both
    // one step at a time: they meet at the entry point.
    public static ListNode CycleStart(ListNode head)
    {
        ListNode slow = head, fast = head;
        while (fast != null && fast.Next != null)
        {
            slow = slow.Next;
            fast = fast.Next.Next;
            if (ReferenceEquals(slow, fast))
            {
                slow = head;
                while (!ReferenceEquals(slow, fast)) { slow = slow.Next; fast = fast.Next; }
                return slow;
            }
        }
        return null;
    }

    public static void Main()
    {
        var a = new ListNode(3); var b = new ListNode(2);
        var c = new ListNode(0); var d = new ListNode(-4);
        a.Next = b; b.Next = c; c.Next = d; d.Next = b;   // cycle back to b

        Console.WriteLine(HasCycle(a));
        Console.WriteLine(CycleStart(a).Val);

        var x = new ListNode(1); var y = new ListNode(2);
        x.Next = y;
        Console.WriteLine(HasCycle(x));
        Console.WriteLine(HasCycle(null));

        var self = new ListNode(1); self.Next = self;      // one-node cycle
        Console.WriteLine(HasCycle(self));
    }
}
```

**Output**

```
True
2
False
False
True
```

**Logic**

Slow and fast pointers. The fast one moves two nodes per step, the slow one moves one, so when the fast pointer reaches the end the slow pointer is at the middle. One pass, O(n) time, O(1) space, and it never needs the length.

The only decision is which middle to return for an even-length list. Looping while `fast != null && fast.Next != null` returns the second of the two; stopping one step earlier returns the first. Both are defensible, so state which one you are giving.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    // Even length: returns the SECOND middle. 1->2->3->4 gives 3.
    public static ListNode MiddleNode(ListNode head)
    {
        ListNode slow = head, fast = head;

        while (fast != null && fast.Next != null)
        {
            slow = slow.Next;
            fast = fast.Next.Next;
        }

        return slow;
    }

    // Even length: returns the FIRST middle. 1->2->3->4 gives 2. This is the one
    // you want when splitting a list for merge sort, so neither half is empty.
    public static ListNode FirstMiddle(ListNode head)
    {
        if (head == null) return null;
        ListNode slow = head, fast = head.Next;

        while (fast != null && fast.Next != null)
        {
            slow = slow.Next;
            fast = fast.Next.Next;
        }

        return slow;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(null)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(MiddleNode(Build(1, 2, 3, 4, 5))));
        Console.WriteLine(Render(MiddleNode(Build(1, 2, 3, 4, 5, 6))));
        Console.WriteLine(Render(FirstMiddle(Build(1, 2, 3, 4, 5, 6))));
        Console.WriteLine(Render(MiddleNode(Build(1))));
        Console.WriteLine(Render(MiddleNode(null)));
    }
}
```

