```
3->4->5
4->5->6
3->4->5->6
1
(null)
```

**Logic**

Walk both lists at once, always appending whichever head is smaller, then advancing that list. When one runs out, attach the remainder of the other wholesale, since it is already sorted. A dummy head node removes the special case for the first element, so there is no need to ask whether the result list is empty on each append. O(n + m) time, O(1) extra space because nodes are relinked rather than copied.

Taking `<=` rather than `<` when the values are equal keeps the relative order of equal elements, which makes the merge stable, the same property that matters in merge sort.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode Merge(ListNode a, ListNode b)
    {
        var dummy = new ListNode();   // avoids a null check on every append
        var tail = dummy;

        while (a != null && b != null)
        {
            if (a.Val <= b.Val) { tail.Next = a; a = a.Next; }   // <= keeps it stable
            else                { tail.Next = b; b = b.Next; }
            tail = tail.Next;
        }

        // Exactly one list is non-empty here, and it is already sorted.
        tail.Next = a ?? b;

        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode head)
    {
        var parts = new List<string>();
        for (var n = head; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join(" -> ", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(Merge(Build(1, 2, 4), Build(1, 3, 4))));
        Console.WriteLine(Render(Merge(Build(), Build())));
        Console.WriteLine(Render(Merge(Build(), Build(0))));
        Console.WriteLine(Render(Merge(Build(5), Build(1, 2, 3))));
    }
}
```

**Output**

```
1 -> 1 -> 2 -> 3 -> 4 -> 4
(empty)
0
1 -> 2 -> 3 -> 5
```

**Logic**

Two pointers separated by exactly n nodes. Advance the leading pointer n steps, then move both together; when the leader reaches the end, the trailing pointer sits just before the node to delete. One pass, O(n) time, O(1) space.

A dummy node in front of the head removes the special case where the node to delete is the head itself, which is where this problem usually breaks. With the dummy, deletion is always 'skip the node after the trailing pointer'.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode RemoveNthFromEnd(ListNode head, int n)
    {
        var dummy = new ListNode(0, head);      // makes deleting the head ordinary
        ListNode lead = dummy, trail = dummy;

        // Open a gap of exactly n nodes between the two pointers.
        for (int i = 0; i < n; i++)
        {
            if (lead.Next == null) return head;  // n is larger than the list
            lead = lead.Next;
        }

        // Move together; when lead hits the last node, trail is before the target.
        while (lead.Next != null)
        {
            lead = lead.Next;
            trail = trail.Next;
        }

        trail.Next = trail.Next.Next;            // unlink
        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(RemoveNthFromEnd(Build(1, 2, 3, 4, 5), 2)));
        Console.WriteLine(Render(RemoveNthFromEnd(Build(1, 2, 3, 4, 5), 5)));  // the head
        Console.WriteLine(Render(RemoveNthFromEnd(Build(1, 2, 3, 4, 5), 1)));  // the tail
        Console.WriteLine(Render(RemoveNthFromEnd(Build(1), 1)));              // empties it
        Console.WriteLine(Render(RemoveNthFromEnd(Build(1, 2), 3)));           // n too large
    }
}
```

