```
1->2->3->5
2->3->4->5
1->2->3->4
(empty)
1->2
```

**Logic**

Because the digits are stored least-significant first, the lists line up exactly the way long addition works: walk both together, add the digits plus the carry, write the units digit and carry the tens. Continue while either list has nodes left or a carry remains, so a final carry produces one more node.

O(max(m, n)) time, O(1) extra space beyond the result. A dummy head again removes the special case for the first digit.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode AddTwoNumbers(ListNode a, ListNode b)
    {
        var dummy = new ListNode();
        var tail = dummy;
        int carry = 0;

        // The carry is part of the loop condition: 5 + 5 must produce a second node.
        while (a != null || b != null || carry != 0)
        {
            int sum = carry;
            if (a != null) { sum += a.Val; a = a.Next; }
            if (b != null) { sum += b.Val; b = b.Next; }

            carry = sum / 10;
            tail.Next = new ListNode(sum % 10);
            tail = tail.Next;
        }

        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        // 342 + 465 = 807, stored reversed
        Console.WriteLine(Render(AddTwoNumbers(Build(2, 4, 3), Build(5, 6, 4))));

        Console.WriteLine(Render(AddTwoNumbers(Build(0), Build(0))));
        Console.WriteLine(Render(AddTwoNumbers(Build(5), Build(5))));            // carry creates a node
        Console.WriteLine(Render(AddTwoNumbers(Build(9, 9, 9), Build(1))));      // cascading carry
        Console.WriteLine(Render(AddTwoNumbers(Build(1, 8), Build(0))));         // different lengths
    }
}
```

**Output**

```
7->0->8
0
0->1
0->0->0->1
1->8
```

**Logic**

Three steps, each a technique worth knowing on its own. Find the middle with slow and fast pointers. Reverse the second half in place. Then merge the two halves alternately, taking one node from each.

Splitting at the first middle matters: it keeps the second half no longer than the first, so the interleaving terminates cleanly with the first half's node last. O(n) time, O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static void ReorderList(ListNode head)
    {
        if (head?.Next == null) return;

        // 1. First middle, so the second half is never the longer one.
        ListNode slow = head, fast = head.Next;
        while (fast?.Next != null) { slow = slow.Next; fast = fast.Next.Next; }

        // 2. Detach and reverse the second half.
        ListNode second = Reverse(slow.Next);
        slow.Next = null;

        // 3. Interleave.
        ListNode first = head;
        while (second != null)
        {
            ListNode nextFirst = first.Next;
            ListNode nextSecond = second.Next;

            first.Next = second;
            second.Next = nextFirst;

            first = nextFirst;
            second = nextSecond;
        }
    }

    private static ListNode Reverse(ListNode head)
    {
        ListNode prev = null, current = head;
        while (current != null)
        {
            ListNode next = current.Next;
            current.Next = prev;
            prev = current;
            current = next;
        }
        return prev;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    private static string Reordered(params int[] values)
    {
        var list = Build(values);
        ReorderList(list);
        return Render(list);
    }

    public static void Main()
    {
        Console.WriteLine(Reordered(1, 2, 3, 4));
        Console.WriteLine(Reordered(1, 2, 3, 4, 5));
        Console.WriteLine(Reordered(1, 2));
        Console.WriteLine(Reordered(1));
        Console.WriteLine(Reordered(1, 2, 3));
        Console.WriteLine(Render(null));
    }
}
```

**Output**

```
1->4->2->3
1->5->2->4->3
1->2
1
1->3->2
(empty)
```

**Logic**

Find the middle with slow and fast pointers, reverse the second half in place, then walk the two halves together comparing values. O(n) time and O(1) space.

The courteous detail is restoring the list before returning: a method named `IsPalindrome` that silently leaves its input reversed is a nasty surprise for the caller. Copying the values into a list and using two pointers is simpler but O(n) space, which is the answer the interviewer is asking you to improve on.

**Program**

```csharp
using System;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static bool IsPalindrome(ListNode head)
    {
        if (head?.Next == null) return true;     // empty or single node

        // 1. Find the first middle, so the second half is never longer.
        ListNode slow = head, fast = head.Next;
        while (fast != null && fast.Next != null)
        {
            slow = slow.Next;
            fast = fast.Next.Next;
        }

        // 2. Reverse the second half, detaching it from the first.
        ListNode secondHalf = Reverse(slow.Next);
        slow.Next = null;

        // 3. Compare. The second half may be one shorter on odd lengths, which is
        //    why it drives the loop: the extra middle element is irrelevant.
        bool palindrome = true;
        for (ListNode a = head, b = secondHalf; b != null; a = a.Next, b = b.Next)
            if (a.Val != b.Val) { palindrome = false; break; }

        // 4. Put the list back the way it was found.
        slow.Next = Reverse(secondHalf);

        return palindrome;
    }

    private static ListNode Reverse(ListNode head)
    {
        ListNode prev = null, current = head;
        while (current != null)
        {
            ListNode next = current.Next;
            current.Next = prev;
            prev = current;
            current = next;
        }
        return prev;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    public static void Main()
    {
        Console.WriteLine(IsPalindrome(Build(1, 2, 2, 1)));
        Console.WriteLine(IsPalindrome(Build(1, 2)));
        Console.WriteLine(IsPalindrome(Build(1, 2, 3, 2, 1)));   // odd length
        Console.WriteLine(IsPalindrome(Build(1)));
        Console.WriteLine(IsPalindrome(null));
        Console.WriteLine(IsPalindrome(Build(1, 0, 1)));

        // The list survives the check unmodified.
        var list = Build(1, 2, 2, 1);
        IsPalindrome(list);
        var parts = new System.Collections.Generic.List<string>();
        for (var n = list; n != null; n = n.Next) parts.Add(n.Val.ToString());
        Console.WriteLine(string.Join("->", parts));
    }
}
```

**Output**

```
True
False
True
True
True
True
1->2->2->1
```

**Logic**

The elegant solution: walk both lists at once, and when a pointer reaches the end, redirect it to the other list's head. Each pointer then travels exactly `lengthA + lengthB` nodes, so they arrive at the intersection simultaneously regardless of the different prefix lengths. If there is no intersection, both reach null together and the loop ends.

That switch is what cancels out the length difference without measuring it. O(m + n) time, O(1) space.

**Program**

```csharp
using System;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0) { Val = val; }
}

public class Solution
{
    public static ListNode GetIntersection(ListNode a, ListNode b)
    {
        if (a == null || b == null) return null;

        ListNode p = a, q = b;

        // Each pointer walks lengthA + lengthB, so the offsets cancel out.
        while (!ReferenceEquals(p, q))
        {
            p = p == null ? b : p.Next;
            q = q == null ? a : q.Next;
        }

        return p;   // the shared node, or null if they never meet
    }

    public static void Main()
    {
        // a: 4 -> 1 -\
        //             8 -> 4 -> 5
        // b: 5 -> 6 -> 1 -/
        var shared = new ListNode(8);
        shared.Next = new ListNode(4) { Next = new ListNode(5) };

        var a = new ListNode(4) { Next = new ListNode(1) { Next = shared } };
        var b = new ListNode(5) { Next = new ListNode(6) { Next = new ListNode(1) { Next = shared } } };

        Console.WriteLine(GetIntersection(a, b).Val);
        Console.WriteLine(ReferenceEquals(GetIntersection(a, b), shared));

        // No intersection: equal values but distinct nodes.
        var x = new ListNode(1) { Next = new ListNode(2) };
        var y = new ListNode(1) { Next = new ListNode(2) };
        Console.WriteLine(GetIntersection(x, y) == null);

        Console.WriteLine(GetIntersection(a, null) == null);

        // The whole of one list is shared.
        Console.WriteLine(GetIntersection(shared, a).Val);
    }
}
```

**Output**

```
8
True
True
True
8
```

**Logic**

A random pointer may target any node, including one not yet copied, so a single forward pass cannot resolve it. The straightforward fix is a dictionary from original node to its clone, filled in one pass and used to wire both `next` and `random` in a second pass.

The O(1)-space trick weaves the clones into the original list: place each clone directly after its source, so a node's clone is always at `node.Next`. That makes `clone.Random = node.Random.Next` a direct lookup with no map at all. A third pass unweaves the two lists.

O(n) time either way.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Node
{
    public int Val;
    public Node Next;
    public Node Random;
    public Node(int val) { Val = val; }
}

public class Solution
{
    // Dictionary version: two passes, O(n) extra space, obviously correct.
    public static Node CopyWithMap(Node head)
    {
        if (head == null) return null;

        var map = new Dictionary<Node, Node>();
        for (var n = head; n != null; n = n.Next) map[n] = new Node(n.Val);

        for (var n = head; n != null; n = n.Next)
        {
            map[n].Next = n.Next == null ? null : map[n.Next];
            map[n].Random = n.Random == null ? null : map[n.Random];
        }

        return map[head];
    }

    // Weaving version: O(1) extra space. Clone sits directly after its source.
    public static Node CopyInterleaved(Node head)
    {
        if (head == null) return null;

        // 1. A -> A' -> B -> B' -> ...
        for (var n = head; n != null; n = n.Next.Next)
        {
            var clone = new Node(n.Val) { Next = n.Next };
            n.Next = clone;
        }

        // 2. A clone's random is the clone of the original's random, which is
        //    always the node right after it.
        for (var n = head; n != null; n = n.Next.Next)
            n.Next.Random = n.Random?.Next;

        // 3. Unweave, restoring the original list exactly as it was.
        var copyHead = head.Next;
        for (var n = head; n != null; n = n.Next)
        {
            var clone = n.Next;
            n.Next = clone.Next;
            clone.Next = n.Next?.Next;
        }

        return copyHead;
    }

    private static string Describe(Node head)
    {
        var index = new Dictionary<Node, int>();
        int i = 0;
        for (var n = head; n != null; n = n.Next) index[n] = i++;

        var parts = new List<string>();
        for (var n = head; n != null; n = n.Next)
            parts.Add($"{n.Val}(r:{(n.Random == null ? "null" : index[n.Random].ToString())})");

        return parts.Count == 0 ? "(empty)" : string.Join(" ", parts);
    }

    private static Node Build()
    {
        var a = new Node(7); var b = new Node(13); var c = new Node(11);
        a.Next = b; b.Next = c;
        a.Random = null; b.Random = a; c.Random = c;   // c points at itself
        return a;
    }

    public static void Main()
    {
        var original = Build();
        Console.WriteLine(Describe(original));

        Console.WriteLine(Describe(CopyWithMap(original)));

        var copy = CopyInterleaved(original);
        Console.WriteLine(Describe(copy));
        Console.WriteLine(Describe(original));           // restored, not corrupted
        Console.WriteLine(ReferenceEquals(copy, original));
        Console.WriteLine(Describe(CopyWithMap(null)));
    }
}
```

