**Logic**

Two good approaches. A min-heap holding the current head of every list: pop the smallest, append it, push its successor. Each of the N nodes enters and leaves a heap of size at most k, giving O(N log k) time and O(k) space.

Or merge pairwise in rounds, halving the number of lists each round until one remains. That is also O(N log k), needs no heap, and reuses the two-list merge you already have.

The approach to avoid is merging one list at a time into an accumulator: the accumulator is re-walked on every merge, making it O(Nk).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    // Heap: O(N log k). PriorityQueue is built in from .NET 6.
    public static ListNode MergeKHeap(ListNode[] lists)
    {
        var heap = new PriorityQueue<ListNode, int>();
        foreach (var head in lists)
            if (head != null) heap.Enqueue(head, head.Val);

        var dummy = new ListNode();
        var tail = dummy;

        while (heap.Count > 0)
        {
            var node = heap.Dequeue();
            tail.Next = node;
            tail = node;

            if (node.Next != null) heap.Enqueue(node.Next, node.Next.Val);
        }

        tail.Next = null;      // the last node may still point into its old list
        return dummy.Next;
    }

    // Pairwise halving: same complexity, no heap, reuses the two-list merge.
    public static ListNode MergeKPairwise(ListNode[] lists)
    {
        if (lists == null || lists.Length == 0) return null;

        var current = new List<ListNode>(lists);
        while (current.Count > 1)
        {
            var next = new List<ListNode>();
            for (int i = 0; i < current.Count; i += 2)
                next.Add(i + 1 < current.Count ? Merge2(current[i], current[i + 1]) : current[i]);
            current = next;
        }
        return current[0];
    }

    private static ListNode Merge2(ListNode a, ListNode b)
    {
        var dummy = new ListNode();
        var tail = dummy;
        while (a != null && b != null)
        {
            if (a.Val <= b.Val) { tail.Next = a; a = a.Next; }
            else                { tail.Next = b; b = b.Next; }
            tail = tail.Next;
        }
        tail.Next = a ?? b;
        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(MergeKHeap(new[] {
            Build(1, 4, 5), Build(1, 3, 4), Build(2, 6) })));

        Console.WriteLine(Render(MergeKPairwise(new[] {
            Build(1, 4, 5), Build(1, 3, 4), Build(2, 6) })));

        Console.WriteLine(Render(MergeKHeap(new ListNode[0])));
        Console.WriteLine(Render(MergeKHeap(new ListNode[] { null, null })));
        Console.WriteLine(Render(MergeKPairwise(new[] { Build(3), null, Build(1, 2) })));
    }
}
```

