1->1->2->3->4->4->5->6
(empty)
(empty)
1->2->3
```

**Logic**

Process the list in blocks of k. For each block, first check that k nodes actually remain, because a trailing partial group must be left untouched. Then reverse exactly k nodes and reconnect the block to what precedes and follows it.

A dummy head removes the special case for the first group, whose reversal changes the list head. Each node is visited a constant number of times, so O(n) time and O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode ReverseKGroup(ListNode head, int k)
    {
        if (head == null || k <= 1) return head;

        var dummy = new ListNode(0, head);
        var groupPrev = dummy;

        while (true)
        {
            // Is a full group of k available? A partial tail is left alone.
            var check = groupPrev;
            for (int i = 0; i < k && check != null; i++) check = check.Next;
            if (check == null) break;

            var groupStart = groupPrev.Next;   // becomes the group's tail
            var next = groupStart;
            ListNode prev = null;

            for (int i = 0; i < k; i++)        // reverse exactly k nodes
            {
                var temp = next.Next;
                next.Next = prev;
                prev = next;
                next = temp;
            }

            groupPrev.Next = prev;             // predecessor now points at the new head
            groupStart.Next = next;            // old head, now tail, points at the remainder
            groupPrev = groupStart;            // advance to the end of this group
        }

        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(ReverseKGroup(Build(1, 2, 3, 4, 5), 2)));
        Console.WriteLine(Render(ReverseKGroup(Build(1, 2, 3, 4, 5), 3)));
        Console.WriteLine(Render(ReverseKGroup(Build(1, 2, 3, 4, 5), 1)));
        Console.WriteLine(Render(ReverseKGroup(Build(1, 2, 3), 5)));   // k exceeds the length
        Console.WriteLine(Render(ReverseKGroup(Build(1, 2, 3, 4), 4)));
        Console.WriteLine(Render(ReverseKGroup(null, 2)));
    }
}
```

