1->2->3
1
1->2->5
2->3
(empty)
```

**Logic**

Close the list into a ring, then break it at the right place. Walk to the tail counting the length, connect the tail to the head, then advance `length - k % length` steps from the head to find the new tail, and cut there.

Taking `k % length` first is essential: rotating a 5-node list by 12 is the same as by 2, and without the reduction the walk would run off the end. Forming the ring avoids tracking two pointers separately.

O(n) time, O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode RotateRight(ListNode head, int k)
    {
        if (head?.Next == null || k <= 0) return head;

        // 1. Find the tail and the length in one walk.
        int length = 1;
        var tail = head;
        while (tail.Next != null) { tail = tail.Next; length++; }

        k %= length;                  // a full turn is a no-op
        if (k == 0) return head;

        // 2. Close the ring.
        tail.Next = head;

        // 3. Walk to the new tail and cut.
        var newTail = head;
        for (int i = 1; i < length - k; i++) newTail = newTail.Next;

        var newHead = newTail.Next;
        newTail.Next = null;

        return newHead;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(RotateRight(Build(1, 2, 3, 4, 5), 2)));
        Console.WriteLine(Render(RotateRight(Build(0, 1, 2), 4)));      // 4 % 3 = 1
        Console.WriteLine(Render(RotateRight(Build(1, 2, 3), 3)));      // full turn
        Console.WriteLine(Render(RotateRight(Build(1, 2), 1)));
        Console.WriteLine(Render(RotateRight(Build(1), 99)));
        Console.WriteLine(Render(RotateRight(null, 1)));
    }
}
```

