**Logic**

Walk the list rewiring two nodes at a time. For each pair, the predecessor points at the second node, the second points at the first, and the first points at whatever followed the pair. Then advance the predecessor to the first node, which is now the pair's tail.

A dummy head removes the special case for the opening pair, whose swap changes the list head. An odd trailing node is left alone, which falls out naturally from requiring both `current` and `current.Next` to exist.

The question specifies swapping nodes rather than values, so exchanging the payloads would be considered cheating.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode SwapPairs(ListNode head)
    {
        var dummy = new ListNode(0, head);
        var prev = dummy;

        // Both nodes of the pair must exist; a lone trailing node stays put.
        while (prev.Next != null && prev.Next.Next != null)
        {
            var first = prev.Next;
            var second = first.Next;

            first.Next = second.Next;   // first now points past the pair
            second.Next = first;        // second takes the lead
            prev.Next = second;         // predecessor points at the new leader

            prev = first;               // first is now the pair's tail
        }

        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(SwapPairs(Build(1, 2, 3, 4))));
        Console.WriteLine(Render(SwapPairs(Build(1, 2, 3))));     // odd tail untouched
        Console.WriteLine(Render(SwapPairs(Build(1))));
        Console.WriteLine(Render(SwapPairs(null)));
        Console.WriteLine(Render(SwapPairs(Build(1, 2))));
        Console.WriteLine(Render(SwapPairs(Build(1, 2, 3, 4, 5, 6))));
    }
}
