**Logic**

A queue is first-in-first-out, a stack is last-in-first-out, so one must be reversed to emulate the other. The cost lands on either push or pop, and you choose which.

For a queue from two stacks, the amortised solution is elegant: push onto an inbox stack, and pop from an outbox stack, refilling the outbox from the inbox only when it is empty. Each element moves between stacks at most once, so despite an occasional O(n) transfer, the amortised cost per operation is O(1).

For a stack from one queue, push then rotate the queue so the new element is at the front, making push O(n) and pop O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

// Queue from two stacks: amortised O(1) per operation.
public class QueueFromStacks
{
    private readonly Stack<int> _inbox = new();
    private readonly Stack<int> _outbox = new();

    public void Enqueue(int value) => _inbox.Push(value);

    public int Dequeue()
    {
        ShiftIfNeeded();
        if (_outbox.Count == 0) throw new InvalidOperationException("queue is empty");
        return _outbox.Pop();
    }

    public int Peek()
    {
        ShiftIfNeeded();
        if (_outbox.Count == 0) throw new InvalidOperationException("queue is empty");
        return _outbox.Peek();
    }

    public int Count => _inbox.Count + _outbox.Count;

    // Only refill when the outbox is empty: that is what makes it amortised O(1).
    private void ShiftIfNeeded()
    {
        if (_outbox.Count > 0) return;
        while (_inbox.Count > 0) _outbox.Push(_inbox.Pop());
    }
}

// Stack from a single queue: push rotates, so push is O(n) and pop is O(1).
public class StackFromQueue
{
    private readonly Queue<int> _queue = new();

    public void Push(int value)
    {
        _queue.Enqueue(value);
        for (int i = 0; i < _queue.Count - 1; i++)
            _queue.Enqueue(_queue.Dequeue());   // bring the new element to the front
    }

    public int Pop() => _queue.Count > 0
        ? _queue.Dequeue()
        : throw new InvalidOperationException("stack is empty");

    public int Count => _queue.Count;
}

public class Solution
{
    public static void Main()
    {
        var q = new QueueFromStacks();
        q.Enqueue(1); q.Enqueue(2); q.Enqueue(3);
        Console.WriteLine(q.Dequeue());
        q.Enqueue(4);                      // arrives while the outbox still has items
        Console.WriteLine(q.Dequeue());
        Console.WriteLine(q.Peek());
        Console.WriteLine(q.Count);

        var s = new StackFromQueue();
        s.Push(1); s.Push(2); s.Push(3);
        Console.WriteLine(s.Pop());
        Console.WriteLine(s.Pop());

        try { new QueueFromStacks().Dequeue(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
