**Logic**

Keep a second stack of minimums alongside the main one. On push, also push the smaller of the new value and the current minimum, so the auxiliary stack's top is always the minimum of everything currently in the stack. On pop, pop both. Every operation is O(1), at the cost of O(n) extra space.

The reason a single tracked minimum fails is that popping the minimum must restore the *previous* minimum, which requires history. The auxiliary stack is that history, aligned one-for-one with the main stack so the two never drift apart.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class MinStack
{
    private readonly Stack<int> _values = new();
    private readonly Stack<int> _minima = new();   // minimum of everything below and including

    public void Push(int value)
    {
        _values.Push(value);
        _minima.Push(_minima.Count == 0 ? value : Math.Min(value, _minima.Peek()));
    }

    public void Pop()
    {
        if (_values.Count == 0) throw new InvalidOperationException("stack is empty");
        _values.Pop();
        _minima.Pop();          // popped together, so the two stacks stay aligned
    }

    public int Top() => _values.Count > 0
        ? _values.Peek()
        : throw new InvalidOperationException("stack is empty");

    public int GetMin() => _minima.Count > 0
        ? _minima.Peek()
        : throw new InvalidOperationException("stack is empty");

    public int Count => _values.Count;
}

public class Solution
{
    public static void Main()
    {
        var s = new MinStack();
        s.Push(-2); s.Push(0); s.Push(-3);

        Console.WriteLine(s.GetMin());   // -3
        s.Pop();
        Console.WriteLine(s.Top());      // 0
        Console.WriteLine(s.GetMin());   // back to -2

        // Duplicated minimum: both copies must be recorded, or the second pop
        // would wrongly discard the minimum while a copy is still present.
        var d = new MinStack();
        d.Push(1); d.Push(1); d.Push(2);
        Console.WriteLine(d.GetMin());
        d.Pop(); d.Pop();
        Console.WriteLine(d.GetMin());

        try { new MinStack().GetMin(); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
}
```

