**Logic**

A stack. Push numbers; on an operator, pop two operands, apply, push the result. Postfix needs no parentheses and no precedence rules, because the order is already unambiguous, which is exactly why compilers convert to it.

The detail that catches people is operand order: the *second* pop is the left operand. It makes no difference for addition and multiplication, and gives the wrong sign or quotient for subtraction and division.

O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int EvalRpn(string[] tokens)
    {
        if (tokens == null || tokens.Length == 0) throw new ArgumentException("empty expression");

        var stack = new Stack<int>();

        foreach (string token in tokens)
        {
            if (token.Length > 1 || !"+-*/".Contains(token))
            {
                stack.Push(int.Parse(token));    // negative numbers are longer than one char
                continue;
            }

            if (stack.Count < 2) throw new ArgumentException("malformed expression");

            int right = stack.Pop();
            int left = stack.Pop();              // SECOND pop is the LEFT operand

            stack.Push(token switch
            {
                "+" => left + right,
                "-" => left - right,
                "*" => left * right,
                "/" => right == 0
                    ? throw new DivideByZeroException()
                    : left / right,              // C# truncates toward zero, as required
                _ => throw new ArgumentException($"unknown operator {token}"),
            });
        }

        if (stack.Count != 1) throw new ArgumentException("malformed expression");
        return stack.Pop();
    }

    public static void Main()
    {
        Console.WriteLine(EvalRpn(new[] { "2", "1", "+", "3", "*" }));      // (2+1)*3
        Console.WriteLine(EvalRpn(new[] { "4", "13", "5", "/", "+" }));     // 4 + 13/5
        Console.WriteLine(EvalRpn(new[] { "5", "3", "-" }));                // order matters
        Console.WriteLine(EvalRpn(new[] { "-7", "2", "/" }));               // truncates to -3
        Console.WriteLine(EvalRpn(new[] { "42" }));

        try { EvalRpn(new[] { "1", "0", "/" }); }
        catch (DivideByZeroException) { Console.WriteLine("divide by zero"); }
    }
}
