**Logic**

A monotonic decreasing stack of indices. For each day, pop every index whose temperature is lower than today's: today is that day's answer, and the wait is the difference in indices. Then push today.

Each index is pushed and popped at most once, so O(n) despite the inner loop. Anything still on the stack at the end never found a warmer day and keeps its default of zero.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int[] DailyTemperatures(int[] temperatures)
    {
        var answer = new int[temperatures.Length];   // defaults to 0: never warmer
        var stack = new Stack<int>();                // indices, temperatures decreasing

        for (int day = 0; day < temperatures.Length; day++)
        {
            // Today resolves every colder day still waiting.
            while (stack.Count > 0 && temperatures[stack.Peek()] < temperatures[day])
            {
                int earlier = stack.Pop();
                answer[earlier] = day - earlier;
            }

            stack.Push(day);
        }

        return answer;
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(",", DailyTemperatures(
            new[] { 73, 74, 75, 71, 69, 72, 76, 73 })));

        Console.WriteLine(string.Join(",", DailyTemperatures(new[] { 30, 40, 50, 60 })));
        Console.WriteLine(string.Join(",", DailyTemperatures(new[] { 30, 60, 90 })));
        Console.WriteLine(string.Join(",", DailyTemperatures(new[] { 90, 80, 70 })));
        Console.WriteLine(string.Join(",", DailyTemperatures(new[] { 50, 50, 50 })));
        Console.WriteLine(string.Join(",", DailyTemperatures(new[] { 42 })));
    }
}
```

