**Logic**

The same monotonic decreasing stack as daily temperatures, but recording the value rather than the distance. Pop every index whose value is smaller than the current one, assigning the current value as its answer, then push the current index. Anything left has no greater element to its right.

For the circular variant, iterate twice over the array using modulo indexing, pushing only during the first pass, so elements can find a greater value that wraps around.

O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int[] NextGreater(int[] nums)
    {
        var answer = new int[nums.Length];
        Array.Fill(answer, -1);            // -1 means "none to the right"

        var stack = new Stack<int>();      // indices, values decreasing

        for (int i = 0; i < nums.Length; i++)
        {
            while (stack.Count > 0 && nums[stack.Peek()] < nums[i])
                answer[stack.Pop()] = nums[i];

            stack.Push(i);
        }

        return answer;
    }

    // Circular: walk twice, but only push during the first pass.
    public static int[] NextGreaterCircular(int[] nums)
    {
        int n = nums.Length;
        var answer = new int[n];
        Array.Fill(answer, -1);

        var stack = new Stack<int>();

        for (int i = 0; i < n * 2; i++)
        {
            int index = i % n;

            while (stack.Count > 0 && nums[stack.Peek()] < nums[index])
                answer[stack.Pop()] = nums[index];

            if (i < n) stack.Push(index);   // second pass only resolves, never adds
        }

        return answer;
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(",", NextGreater(new[] { 2, 1, 2, 4, 3 })));
        Console.WriteLine(string.Join(",", NextGreater(new[] { 1, 2, 3, 4 })));
        Console.WriteLine(string.Join(",", NextGreater(new[] { 4, 3, 2, 1 })));
        Console.WriteLine(string.Join(",", NextGreater(new[] { 5, 5, 5 })));
        Console.WriteLine(string.Join(",", NextGreaterCircular(new[] { 1, 2, 1 })));
        Console.WriteLine(string.Join(",", NextGreaterCircular(new[] { 5, 4, 3, 2, 1 })));
    }
}
```

