**Logic**

Nested repetition, so a stack. Two stacks in fact, or one of pairs: when an opening bracket is met, push the repeat count and the text built so far, then start a fresh buffer. On a closing bracket, pop both and append the new buffer repeated that many times.

Digits must be accumulated across characters, since a count may be multi-digit. The saved-prefix technique is what handles nesting correctly without recursion.

O(length of output) time.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    public static string DecodeString(string s)
    {
        if (string.IsNullOrEmpty(s)) return "";

        var counts = new Stack<int>();
        var prefixes = new Stack<string>();
        var current = new StringBuilder();
        int number = 0;

        foreach (char c in s)
        {
            if (char.IsAsciiDigit(c))
            {
                number = number * 10 + (c - '0');    // multi-digit counts
            }
            else if (c == '[')
            {
                counts.Push(number);
                prefixes.Push(current.ToString());    // park what came before
                number = 0;
                current.Clear();
            }
            else if (c == ']')
            {
                string inner = current.ToString();
                current.Clear();
                current.Append(prefixes.Pop());

                int repeat = counts.Pop();
                for (int i = 0; i < repeat; i++) current.Append(inner);
            }
            else
            {
                current.Append(c);
            }
        }

        return current.ToString();
    }

    public static void Main()
    {
        Console.WriteLine(DecodeString("3[a]2[bc]"));
        Console.WriteLine(DecodeString("3[a2[c]]"));      // nested
        Console.WriteLine(DecodeString("2[abc]3[cd]ef"));
        Console.WriteLine(DecodeString("abc"));           // no brackets
        Console.WriteLine(DecodeString("10[a]"));         // multi-digit count
        Console.WriteLine(DecodeString("2[]"));           // empty body
    }
}
```

