abcabccdcdcdef
abc
aaaaaaaaaa

```

**Logic**

With only addition, subtraction and parentheses, no operator precedence is involved, so a single running total works. Keep a sign multiplier of plus or minus one, and on an opening bracket push both the total so far and the sign, then reset.

On a closing bracket, multiply the bracketed result by the saved sign and add it to the saved total. That handles the awkward case of a minus in front of a parenthesis, which flips the sign of everything inside.

O(n) time, O(depth) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int Calculate(string s)
    {
        if (string.IsNullOrEmpty(s)) return 0;

        var stack = new Stack<int>();    // alternating: saved total, saved sign
        int total = 0, sign = 1, number = 0;

        foreach (char c in s)
        {
            if (char.IsAsciiDigit(c))
            {
                number = number * 10 + (c - '0');
            }
            else if (c == '+' || c == '-')
            {
                total += sign * number;      // settle the pending number
                number = 0;
                sign = c == '+' ? 1 : -1;
            }
            else if (c == '(')
            {
                stack.Push(total);           // park the context
                stack.Push(sign);
                total = 0;
                sign = 1;
            }
            else if (c == ')')
            {
                total += sign * number;
                number = 0;

                total *= stack.Pop();        // the sign in front of the bracket
                total += stack.Pop();        // the total before the bracket
                sign = 1;
            }
            // whitespace and anything else is ignored
        }

        return total + sign * number;        // settle the final number
    }

    public static void Main()
    {
        Console.WriteLine(Calculate("1 + 1"));
        Console.WriteLine(Calculate(" 2-1 + 2 "));
        Console.WriteLine(Calculate("(1+(4+5+2)-3)+(6+8)"));
        Console.WriteLine(Calculate("2-(5-6)"));          // minus before a bracket
        Console.WriteLine(Calculate("-(3+4)"));           // leading unary minus
        Console.WriteLine(Calculate("100"));
    }
}
```

