3
-7
100
```

**Logic**

A fixed array with head and tail indices that wrap using modulo. Enqueue writes at the tail and advances it; dequeue reads at the head and advances that. Both are O(1), and no elements are ever shifted, which is the point: a naive array queue that shifts on dequeue is O(n) per removal.

Full and empty both make head equal tail, so they need distinguishing. The cleanest way is to keep an explicit count; the alternative is to waste one slot so that full and empty are never the same configuration.

**Program**

```csharp
using System;

public class CircularQueue
{
    private readonly int[] _items;
    private int _head;
    private int _count;      // explicit count: full and empty are otherwise identical

    public CircularQueue(int capacity)
    {
        if (capacity <= 0) throw new ArgumentOutOfRangeException(nameof(capacity));
        _items = new int[capacity];
    }

    public int Count => _count;
    public bool IsFull => _count == _items.Length;
    public bool IsEmpty => _count == 0;

    public bool Enqueue(int value)
    {
        if (IsFull) return false;

        _items[(_head + _count) % _items.Length] = value;   // tail derived from head + count
        _count++;
        return true;
    }

    public bool Dequeue(out int value)
    {
        if (IsEmpty) { value = default; return false; }

        value = _items[_head];
        _head = (_head + 1) % _items.Length;
        _count--;
        return true;
    }

    public bool Peek(out int value)
    {
        if (IsEmpty) { value = default; return false; }
        value = _items[_head];
        return true;
    }
}

public class Solution
{
    public static void Main()
    {
        var q = new CircularQueue(3);

        Console.WriteLine(q.Enqueue(1));
        Console.WriteLine(q.Enqueue(2));
        Console.WriteLine(q.Enqueue(3));
        Console.WriteLine(q.Enqueue(4));      // full

        q.Dequeue(out int first);
        Console.WriteLine(first);

        Console.WriteLine(q.Enqueue(4));      // space freed, wraps around
        q.Peek(out int head);
        Console.WriteLine(head);
        Console.WriteLine(q.Count);

        var empty = new CircularQueue(1);
        Console.WriteLine(empty.Dequeue(out _));
    }
}
```

