```
True
True
True
False
1
True
2
3
False
```

**Logic**

A stack of indices, seeded with -1 as a base marker. On an open bracket, push its index. On a close, pop: if the stack is then empty, this close is unmatched and its index becomes the new base; otherwise the current length is the distance from the current index back to the new stack top.

The sentinel is what makes the arithmetic uniform, so no special case is needed for a valid substring starting at index 0. O(n) time, O(n) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int LongestValidParentheses(string s)
    {
        if (string.IsNullOrEmpty(s)) return 0;

        var stack = new Stack<int>();
        stack.Push(-1);              // base marker: the position before any match
        int best = 0;

        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '(')
            {
                stack.Push(i);
            }
            else
            {
                stack.Pop();

                if (stack.Count == 0)
                    stack.Push(i);    // unmatched close: it becomes the new base
                else
                    best = Math.Max(best, i - stack.Peek());
            }
        }

        return best;
    }

    public static void Main()
    {
        Console.WriteLine(LongestValidParentheses("(()"));
        Console.WriteLine(LongestValidParentheses(")()())"));
        Console.WriteLine(LongestValidParentheses(""));
        Console.WriteLine(LongestValidParentheses("()(()"));
        Console.WriteLine(LongestValidParentheses("()()"));      // adjacent groups join
        Console.WriteLine(LongestValidParentheses("(((("));
    }
}
```

