4
0
2
4
0
```

**Logic**

A stack of surviving asteroids. A collision is possible only when a right-moving asteroid is already on the stack and a left-moving one arrives, since that is the only configuration where their paths cross.

On such a meeting, compare sizes: the smaller is destroyed, and equal sizes destroy both. The incoming asteroid may survive several collisions in a row, so the comparison loops until it is destroyed or nothing on the stack opposes it.

Each asteroid is pushed and popped at most once, so O(n).

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int[] AsteroidCollision(int[] asteroids)
    {
        var stack = new Stack<int>();

        foreach (int incoming in asteroids)
        {
            int current = incoming;
            bool destroyed = false;

            // A collision needs a right-mover on the stack and a left-mover arriving.
            while (!destroyed && current < 0 && stack.Count > 0 && stack.Peek() > 0)
            {
                int top = stack.Peek();

                if (top < -current) stack.Pop();            // the one on the stack loses
                else if (top == -current) { stack.Pop(); destroyed = true; }   // both go
                else destroyed = true;                       // the incoming one loses
            }

            if (!destroyed) stack.Push(current);
        }

        return stack.Reverse().ToArray();   // stack pops newest-first
    }

    private static string Show(int[] a) => a.Length == 0 ? "(none)" : string.Join(",", a);

    public static void Main()
    {
        Console.WriteLine(Show(AsteroidCollision(new[] { 5, 10, -5 })));
        Console.WriteLine(Show(AsteroidCollision(new[] { 8, -8 })));        // equal: both die
        Console.WriteLine(Show(AsteroidCollision(new[] { 10, 2, -5 })));
        Console.WriteLine(Show(AsteroidCollision(new[] { -2, -1, 1, 2 })));  // never meet
        Console.WriteLine(Show(AsteroidCollision(new[] { 1, -2, -2, -2 })));
        Console.WriteLine(Show(AsteroidCollision(new[] { -5 })));
    }
}
