**Logic**

Merge sort is the right choice for a list. Quicksort needs random access for good pivot selection and its partitioning is awkward without indices, while merge sort only ever walks forward and splices, which is exactly what a list supports.

Split at the first middle so both halves are non-empty, sort each recursively, then merge. Splitting at the second middle would leave a two-node list producing an empty half and a two-node half, which recurses forever.

O(n log n) time. Space is O(log n) for the recursion; a bottom-up version reaches O(1).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null) { Val = val; Next = next; }
}

public class Solution
{
    public static ListNode SortList(ListNode head)
    {
        if (head?.Next == null) return head;     // 0 or 1 nodes: already sorted

        // Split at the FIRST middle, so neither half is empty.
        ListNode slow = head, fast = head.Next;
        while (fast?.Next != null) { slow = slow.Next; fast = fast.Next.Next; }

        ListNode second = slow.Next;
        slow.Next = null;                        // detach, or the recursion never ends

        return Merge(SortList(head), SortList(second));
    }

    private static ListNode Merge(ListNode a, ListNode b)
    {
        var dummy = new ListNode();
        var tail = dummy;

        while (a != null && b != null)
        {
            if (a.Val <= b.Val) { tail.Next = a; a = a.Next; }   // <= keeps it stable
            else                { tail.Next = b; b = b.Next; }
            tail = tail.Next;
        }

        tail.Next = a ?? b;
        return dummy.Next;
    }

    private static ListNode Build(params int[] values)
    {
        ListNode head = null;
        for (int i = values.Length - 1; i >= 0; i--) head = new ListNode(values[i], head);
        return head;
    }

    private static string Render(ListNode n)
    {
        var parts = new List<string>();
        for (; n != null; n = n.Next) parts.Add(n.Val.ToString());
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Render(SortList(Build(4, 2, 1, 3))));
        Console.WriteLine(Render(SortList(Build(-1, 5, 3, 4, 0))));
        Console.WriteLine(Render(SortList(Build(1, 2, 3))));      // already sorted
        Console.WriteLine(Render(SortList(Build(3, 2, 1))));      // reversed
        Console.WriteLine(Render(SortList(Build(2, 2, 1, 1))));   // duplicates
        Console.WriteLine(Render(SortList(null)));
    }
}
```

