-1->0->3->4->5
1->2->3
1->2->3
1->1->2->2
(empty)
```

**Logic**

Split on slashes and process each component with a stack. A normal name is pushed; `..` pops one level, if there is one; `.` and empty components, which come from repeated or trailing slashes, are skipped. Joining the stack with slashes gives the canonical path.

The edge cases are what the question is really about: `..` at the root must be ignored rather than escaping above it, the result always begins with a slash, and it never ends with one except for the root itself.

O(n) time and space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static string SimplifyPath(string path)
    {
        if (string.IsNullOrEmpty(path)) return "/";

        var stack = new List<string>();   // a list so it can be joined in order

        foreach (string part in path.Split('/'))
        {
            if (part.Length == 0 || part == ".") continue;      // "//" and "/./"

            if (part == "..")
            {
                // Going up from the root stays at the root.
                if (stack.Count > 0) stack.RemoveAt(stack.Count - 1);
                continue;
            }

            stack.Add(part);
        }

        return "/" + string.Join("/", stack);
    }

    public static void Main()
    {
        Console.WriteLine(SimplifyPath("/home/"));
        Console.WriteLine(SimplifyPath("/../"));                  // cannot go above root
        Console.WriteLine(SimplifyPath("/home//foo/"));           // double slash
        Console.WriteLine(SimplifyPath("/a/./b/../../c/"));
        Console.WriteLine(SimplifyPath("/"));
        Console.WriteLine(SimplifyPath("/a/../../b/../c//.//"));
    }
}
```

**Output**

```
/home
/
/home/foo
/c
/
/c
```

**Logic**

The depth of a tree is one plus the deeper of its two subtrees, and an empty tree has depth 0. That recurrence is the whole solution: recurse both sides, take the larger, add one. Every node is visited once, so O(n) time. Space is O(h) for the call stack, which is O(log n) on a balanced tree but O(n) on a degenerate one.

The iterative alternative is a level-order traversal counting levels, which uses O(w) space for the widest level and avoids the stack-overflow risk entirely.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int MaxDepth(TreeNode root)
    {
        if (root == null) return 0;                    // base case: empty tree
        return 1 + Math.Max(MaxDepth(root.Left), MaxDepth(root.Right));
    }

    // Level-order version: no recursion, so no stack-overflow risk on deep trees.
    public static int MaxDepthIterative(TreeNode root)
    {
        if (root == null) return 0;
        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);
        int depth = 0;

        while (queue.Count > 0)
        {
            int levelSize = queue.Count;               // snapshot: this level only
            for (int i = 0; i < levelSize; i++)
            {
                var node = queue.Dequeue();
                if (node.Left != null) queue.Enqueue(node.Left);
                if (node.Right != null) queue.Enqueue(node.Right);
            }
            depth++;
        }
        return depth;
    }

    public static void Main()
    {
        //     3
        //    / \
        //   9  20
        //     /  \
        //    15   7
        var root = new TreeNode(3,
            new TreeNode(9),
            new TreeNode(20, new TreeNode(15), new TreeNode(7)));

        Console.WriteLine(MaxDepth(root));
        Console.WriteLine(MaxDepthIterative(root));
        Console.WriteLine(MaxDepth(null));
        Console.WriteLine(MaxDepth(new TreeNode(1)));

        // Degenerate: a 1-2-3 right chain behaves like a linked list.
        var chain = new TreeNode(1, null, new TreeNode(2, null, new TreeNode(3)));
        Console.WriteLine(MaxDepth(chain));
    }
}
```

**Output**

```
3
3
0
1
3
```

**Logic**

Swap the left and right child of every node. Recursively: swap the current node's children, then invert each subtree. The order does not matter, since swapping references and recursing are independent. O(n) time, O(h) stack space.

This is famously the question that got the author of Homebrew rejected by Google. It is four lines, and what is really being tested is whether you mutate in place correctly rather than building a new tree by accident.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static TreeNode Invert(TreeNode root)
    {
        if (root == null) return null;

        (root.Left, root.Right) = (root.Right, root.Left);   // tuple swap, no temp
        Invert(root.Left);
        Invert(root.Right);

        return root;
    }

    // Iterative: any traversal works, since the swap is per node and order-free.
    public static TreeNode InvertIterative(TreeNode root)
    {
        if (root == null) return null;
        var stack = new Stack<TreeNode>();
        stack.Push(root);

        while (stack.Count > 0)
        {
            var node = stack.Pop();
            (node.Left, node.Right) = (node.Right, node.Left);
            if (node.Left != null) stack.Push(node.Left);
            if (node.Right != null) stack.Push(node.Right);
        }
        return root;
    }

    private static string LevelOrder(TreeNode root)
    {
        if (root == null) return "(empty)";
        var outp = new List<string>();
        var q = new Queue<TreeNode>();
        q.Enqueue(root);
        while (q.Count > 0)
        {
            var n = q.Dequeue();
            outp.Add(n.Val.ToString());
            if (n.Left != null) q.Enqueue(n.Left);
            if (n.Right != null) q.Enqueue(n.Right);
        }
        return string.Join(",", outp);
    }

    public static void Main()
    {
        //      4
        //    /   \
        //   2     7
        //  / \   / \
        // 1   3 6   9
        var root = new TreeNode(4,
            new TreeNode(2, new TreeNode(1), new TreeNode(3)),
            new TreeNode(7, new TreeNode(6), new TreeNode(9)));

        Console.WriteLine(LevelOrder(root));
        Console.WriteLine(LevelOrder(Invert(root)));
        Console.WriteLine(LevelOrder(InvertIterative(root)));   // back to the original
        Console.WriteLine(LevelOrder(Invert(null)));
    }
}
```

