**Logic**

Compare structurally and by value at the same time. Two trees are identical when both are null, or both are non-null with equal values and identical left and right subtrees. The null handling comes first: both null is true, exactly one null is false.

O(n) time where n is the smaller tree, since a mismatch short-circuits. O(h) stack space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static bool IsSameTree(TreeNode p, TreeNode q)
    {
        if (p == null && q == null) return true;    // both absent: equal
        if (p == null || q == null) return false;   // exactly one absent: differ
        if (p.Val != q.Val) return false;

        return IsSameTree(p.Left, q.Left)
            && IsSameTree(p.Right, q.Right);
    }

    // Iterative: pairs on a stack, so no recursion depth limit.
    public static bool IsSameTreeIterative(TreeNode p, TreeNode q)
    {
        var stack = new Stack<(TreeNode a, TreeNode b)>();
        stack.Push((p, q));

        while (stack.Count > 0)
        {
            var (a, b) = stack.Pop();
            if (a == null && b == null) continue;
            if (a == null || b == null || a.Val != b.Val) return false;

            stack.Push((a.Left, b.Left));
            stack.Push((a.Right, b.Right));
        }
        return true;
    }

    public static void Main()
    {
        var a = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        var b = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        Console.WriteLine(IsSameTree(a, b));

        var c = new TreeNode(1, new TreeNode(2), null);
        var d = new TreeNode(1, null, new TreeNode(2));   // same values, different shape
        Console.WriteLine(IsSameTree(c, d));

        Console.WriteLine(IsSameTree(null, null));
        Console.WriteLine(IsSameTree(new TreeNode(1), null));
        Console.WriteLine(IsSameTree(new TreeNode(1), new TreeNode(2)));
        Console.WriteLine(IsSameTreeIterative(a, b));
    }
}
```

**Output**

```
True
False
True
False
False
True
```

**Logic**

Symmetry is a mirror property between two subtrees, not a property of one. So compare the left subtree against the right with a helper that pairs them crosswise: `left.Left` against `right.Right`, and `left.Right` against `right.Left`.

That crossover is the whole question. Comparing the two subtrees straight across tests whether they are identical, not mirrored, which wrongly rejects a genuinely symmetric tree. O(n) time, O(h) stack.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static bool IsSymmetric(TreeNode root) =>
        root == null || IsMirror(root.Left, root.Right);

    private static bool IsMirror(TreeNode a, TreeNode b)
    {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        if (a.Val != b.Val) return false;

        // Crosswise: outer pair against outer pair, inner against inner.
        return IsMirror(a.Left, b.Right)
            && IsMirror(a.Right, b.Left);
    }

    // Iterative with a queue: push the pairs that must mirror each other.
    public static bool IsSymmetricIterative(TreeNode root)
    {
        if (root == null) return true;
        var queue = new Queue<(TreeNode a, TreeNode b)>();
        queue.Enqueue((root.Left, root.Right));

        while (queue.Count > 0)
        {
            var (a, b) = queue.Dequeue();
            if (a == null && b == null) continue;
            if (a == null || b == null || a.Val != b.Val) return false;

            queue.Enqueue((a.Left, b.Right));
            queue.Enqueue((a.Right, b.Left));
        }
        return true;
    }

    public static void Main()
    {
        //     1
        //    / \
        //   2   2
        //  / \ / \
        // 3  4 4  3
        var sym = new TreeNode(1,
            new TreeNode(2, new TreeNode(3), new TreeNode(4)),
            new TreeNode(2, new TreeNode(4), new TreeNode(3)));
        Console.WriteLine(IsSymmetric(sym));
        Console.WriteLine(IsSymmetricIterative(sym));

        // Same values, but the children are not mirrored.
        var notSym = new TreeNode(1,
            new TreeNode(2, null, new TreeNode(3)),
            new TreeNode(2, null, new TreeNode(3)));
        Console.WriteLine(IsSymmetric(notSym));

        Console.WriteLine(IsSymmetric(null));
        Console.WriteLine(IsSymmetric(new TreeNode(1)));
    }
}
```

**Output**

```
True
True
False
True
True
```

**Logic**

A queue, processing one level at a time. Enqueue the root, then repeatedly take a snapshot of the current queue size, dequeue exactly that many nodes into the current level's list, and enqueue their children for the next round. The snapshot is what separates levels, since children added during the loop belong to the next level.

O(n) time. Space is O(w), the maximum width, which for a complete tree is about n/2 at the bottom level.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static IList<IList<int>> LevelOrder(TreeNode root)
    {
        var levels = new List<IList<int>>();
        if (root == null) return levels;

        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);

        while (queue.Count > 0)
        {
            int levelSize = queue.Count;      // snapshot: this level, not the next
            var level = new List<int>(levelSize);

            for (int i = 0; i < levelSize; i++)
            {
                var node = queue.Dequeue();
                level.Add(node.Val);

                if (node.Left != null) queue.Enqueue(node.Left);
                if (node.Right != null) queue.Enqueue(node.Right);
            }

            levels.Add(level);
        }

        return levels;
    }

    private static string Render(IList<IList<int>> levels) =>
        levels.Count == 0 ? "(empty)"
            : string.Join(" | ", levels.Select(l => "[" + string.Join(",", l) + "]"));

    public static void Main()
    {
        //     3
        //    / \
        //   9  20
        //     /  \
        //    15   7
        var root = new TreeNode(3,
            new TreeNode(9),
            new TreeNode(20, new TreeNode(15), new TreeNode(7)));

        Console.WriteLine(Render(LevelOrder(root)));
        Console.WriteLine(Render(LevelOrder(null)));
        Console.WriteLine(Render(LevelOrder(new TreeNode(1))));

        // Left-leaning chain: one node per level.
        var chain = new TreeNode(1, new TreeNode(2, new TreeNode(3)));
        Console.WriteLine(Render(LevelOrder(chain)));
    }
}
```

