**Logic**

Each traversal replaces the call stack with an explicit one.

In-order: walk left pushing every node, pop and visit, then move right. Pre-order: push the root, then repeatedly pop and visit, pushing right before left so left is processed first. Post-order is the awkward one, because a node can only be visited after both children; the neat trick is to run a modified pre-order visiting root, right, left, then reverse the result.

All three are O(n) time and O(h) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static IList<int> InOrder(TreeNode root)
    {
        var result = new List<int>();
        var stack = new Stack<TreeNode>();
        var node = root;

        while (node != null || stack.Count > 0)
        {
            while (node != null) { stack.Push(node); node = node.Left; }  // dive left
            node = stack.Pop();
            result.Add(node.Val);
            node = node.Right;
        }
        return result;
    }

    public static IList<int> PreOrder(TreeNode root)
    {
        var result = new List<int>();
        if (root == null) return result;

        var stack = new Stack<TreeNode>();
        stack.Push(root);

        while (stack.Count > 0)
        {
            var node = stack.Pop();
            result.Add(node.Val);
            if (node.Right != null) stack.Push(node.Right);   // right first...
            if (node.Left != null) stack.Push(node.Left);     // ...so left pops first
        }
        return result;
    }

    // root-right-left, reversed, gives left-right-root.
    public static IList<int> PostOrder(TreeNode root)
    {
        var result = new List<int>();
        if (root == null) return result;

        var stack = new Stack<TreeNode>();
        stack.Push(root);

        while (stack.Count > 0)
        {
            var node = stack.Pop();
            result.Add(node.Val);
            if (node.Left != null) stack.Push(node.Left);
            if (node.Right != null) stack.Push(node.Right);
        }

        result.Reverse();
        return result;
    }

    public static void Main()
    {
        //     1
        //    / \
        //   2   3
        //  / \
        // 4   5
        var root = new TreeNode(1,
            new TreeNode(2, new TreeNode(4), new TreeNode(5)),
            new TreeNode(3));

        Console.WriteLine(string.Join(",", InOrder(root)));
        Console.WriteLine(string.Join(",", PreOrder(root)));
        Console.WriteLine(string.Join(",", PostOrder(root)));
        Console.WriteLine(string.Join(",", InOrder(null)));
        Console.WriteLine(string.Join(",", PreOrder(new TreeNode(7))));
    }
}
```

**Output**

```
4,2,5,1,3
1,2,4,5,3
4,5,2,3,1

7
```

**Logic**

Preorder gives the root first. Finding that root inside the inorder sequence splits it into everything left of the root and everything right, which are exactly the two subtrees. The size of the left part tells you how many of the following preorder values belong to the left subtree, so both sequences can be partitioned and the process repeats.

Scanning the inorder array for the root each time is O(n²). Building a value-to-index map once makes each lookup O(1), giving O(n) overall.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0) { Val = val; }
}

public class Solution
{
    private static Dictionary<int, int> _inorderIndex;
    private static int _pre;

    public static TreeNode BuildTree(int[] preorder, int[] inorder)
    {
        if (preorder == null || preorder.Length == 0) return null;

        // One map instead of a linear scan per node: O(n) rather than O(n^2).
        _inorderIndex = new Dictionary<int, int>(inorder.Length);
        for (int i = 0; i < inorder.Length; i++) _inorderIndex[inorder[i]] = i;

        _pre = 0;
        return Build(preorder, 0, inorder.Length - 1);
    }

    private static TreeNode Build(int[] preorder, int left, int right)
    {
        if (left > right) return null;

        int value = preorder[_pre++];            // preorder hands us the root
        var node = new TreeNode(value);

        int mid = _inorderIndex[value];          // its position splits inorder

        // Left must be built first: it consumes the preorder values that follow.
        node.Left = Build(preorder, left, mid - 1);
        node.Right = Build(preorder, mid + 1, right);

        return node;
    }

    private static string LevelOrder(TreeNode root)
    {
        if (root == null) return "(empty)";
        var outp = new List<string>();
        var q = new Queue<TreeNode>();
        q.Enqueue(root);
        while (q.Count > 0)
        {
            var n = q.Dequeue();
            outp.Add(n.Val.ToString());
            if (n.Left != null) q.Enqueue(n.Left);
            if (n.Right != null) q.Enqueue(n.Right);
        }
        return string.Join(",", outp);
    }

    public static void Main()
    {
        Console.WriteLine(LevelOrder(BuildTree(
            new[] { 3, 9, 20, 15, 7 },
            new[] { 9, 3, 15, 20, 7 })));

        Console.WriteLine(LevelOrder(BuildTree(new[] { -1 }, new[] { -1 })));
        Console.WriteLine(LevelOrder(BuildTree(new int[0], new int[0])));

        // A right-leaning chain: preorder and inorder are identical.
        Console.WriteLine(LevelOrder(BuildTree(
            new[] { 1, 2, 3 }, new[] { 1, 2, 3 })));

        // A left-leaning chain: inorder is the reverse.
        Console.WriteLine(LevelOrder(BuildTree(
            new[] { 1, 2, 3 }, new[] { 3, 2, 1 })));
    }
}
```

**Output**

```
3,9,20,15,7
-1
(empty)
1,2,3
1,2,3
```

The last two produce the same level-order string but are different trees: one leans right, the other left. That is a good reminder that level-order alone does not identify a tree either.

**Logic**

The right side view is the last node of each level, so it is a level-order traversal that keeps one node per level. Using the level-snapshot pattern, take the element at index `levelSize - 1` of each level.

The common mistake is assuming the answer is always a right child. When the right subtree is shorter, a node from the left subtree becomes visible, so the view is genuinely about depth, not about direction. O(n) time, O(w) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static IList<int> RightSideView(TreeNode root)
    {
        var view = new List<int>();
        if (root == null) return view;

        var queue = new Queue<TreeNode>();
        queue.Enqueue(root);

        while (queue.Count > 0)
        {
            int levelSize = queue.Count;

            for (int i = 0; i < levelSize; i++)
            {
                var node = queue.Dequeue();

                if (i == levelSize - 1) view.Add(node.Val);   // last node on this level

                if (node.Left != null) queue.Enqueue(node.Left);
                if (node.Right != null) queue.Enqueue(node.Right);
            }
        }

        return view;
    }

    public static void Main()
    {
        //   1
        //  / \
        // 2   3
        //  \   \
        //   5   4
        var a = new TreeNode(1,
            new TreeNode(2, null, new TreeNode(5)),
            new TreeNode(3, null, new TreeNode(4)));
        Console.WriteLine(string.Join(",", RightSideView(a)));

        //   1
        //  / \
        // 2   3
        // |
        // 4          4 is visible: the right subtree does not reach that depth
        var b = new TreeNode(1,
            new TreeNode(2, new TreeNode(4), null),
            new TreeNode(3));
        Console.WriteLine(string.Join(",", RightSideView(b)));

        Console.WriteLine(string.Join(",", RightSideView(null)));
        Console.WriteLine(string.Join(",", RightSideView(new TreeNode(1))));

        // A purely left-leaning tree: every node is visible from the right.
        var left = new TreeNode(1, new TreeNode(2, new TreeNode(3), null), null);
        Console.WriteLine(string.Join(",", RightSideView(left)));
    }
}
```

**Output**

```
1,3,4
1,3,4

1
1,2,3
```

**Logic**

Subtract as you descend. At each node, reduce the remaining target by the node's value, then ask the same question of its children. At a leaf, the answer is whether the remainder is exactly zero.

The detail that catches people is what counts as a leaf: a node with no children at all, not a node with one null child. Treating a half-empty node as a leaf accepts paths that stop in mid-air. O(n) time, O(h) stack.

**Program**

```csharp
using System;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static bool HasPathSum(TreeNode root, int target)
    {
        if (root == null) return false;

        int remaining = target - root.Val;

        // A leaf is a node with NO children, not one with a single null child.
        if (root.Left == null && root.Right == null) return remaining == 0;

        return HasPathSum(root.Left, remaining)
            || HasPathSum(root.Right, remaining);
    }

    public static void Main()
    {
        //       5
        //      / \
        //     4   8
        //    /   / \
        //   11  13  4
        //  /  \      \
        // 7    2      1
        var root = new TreeNode(5,
            new TreeNode(4, new TreeNode(11, new TreeNode(7), new TreeNode(2)), null),
            new TreeNode(8, new TreeNode(13), new TreeNode(4, null, new TreeNode(1))));

        Console.WriteLine(HasPathSum(root, 22));   // 5+4+11+2
        Console.WriteLine(HasPathSum(root, 26));   // 5+8+13
        Console.WriteLine(HasPathSum(root, 9));    // 5+4 stops at a non-leaf
        Console.WriteLine(HasPathSum(null, 0));    // no path exists at all
        Console.WriteLine(HasPathSum(new TreeNode(1), 1));

        // Negative values: the sum is not monotonic, so no early exit is possible.
        var neg = new TreeNode(1, new TreeNode(-2, new TreeNode(3), null), null);
        Console.WriteLine(HasPathSum(neg, 2));
    }
}
```

**Output**

```
True
True
False
False
True
True
```

**Logic**

A path may start and end anywhere, so at each node consider the path that turns at it: the node's value plus the best downward contribution from each side. Track the maximum of those as you go.

Two subtleties. First, a negative contribution should be discarded with `Math.Max(0, ...)`, since leaving a subtree out is always at least as good. Second, the value returned to the parent is the node plus only *one* side, because a parent cannot use a path that already turned. That difference between what is recorded and what is returned is the entire problem.

O(n) time, O(h) space.

**Program**

```csharp
using System;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int MaxPathSum(TreeNode root)
    {
        int best = int.MinValue;
        Gain(root, ref best);
        return best;
    }

    // Returns the best DOWNWARD path starting at this node (one side only),
    // while recording the best path that TURNS at this node.
    private static int Gain(TreeNode node, ref int best)
    {
        if (node == null) return 0;

        // A negative branch is worth skipping entirely, hence the clamp at 0.
        int left = Math.Max(0, Gain(node.Left, ref best));
        int right = Math.Max(0, Gain(node.Right, ref best));

        int throughHere = node.Val + left + right;
        if (throughHere > best) best = throughHere;

        return node.Val + Math.Max(left, right);   // the parent can only use one side
    }

    public static void Main()
    {
        Console.WriteLine(MaxPathSum(new TreeNode(1, new TreeNode(2), new TreeNode(3))));

        //    -10
        //    /  \
        //   9   20
        //      /  \
        //     15   7      best is 15+20+7, skipping the root
        var t = new TreeNode(-10,
            new TreeNode(9),
            new TreeNode(20, new TreeNode(15), new TreeNode(7)));
        Console.WriteLine(MaxPathSum(t));

        Console.WriteLine(MaxPathSum(new TreeNode(-3)));            // all negative
        Console.WriteLine(MaxPathSum(new TreeNode(2, new TreeNode(-1), null)));
        Console.WriteLine(MaxPathSum(new TreeNode(-2, new TreeNode(-1), null)));
    }
}
```

**Output**

```
6
42
-3
2
-1
```

**Logic**

An in-order traversal of a BST yields values in ascending order, so the kth element visited is the answer. Do it iteratively with an explicit stack and stop as soon as the count reaches k, rather than materialising the whole traversal.

That early exit matters: it makes the cost O(h + k) rather than O(n), so finding the smallest element in a large balanced tree is logarithmic rather than linear.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int KthSmallest(TreeNode root, int k)
    {
        var stack = new Stack<TreeNode>();
        var node = root;
        int seen = 0;

        while (node != null || stack.Count > 0)
        {
            while (node != null) { stack.Push(node); node = node.Left; }

            node = stack.Pop();
            if (++seen == k) return node.Val;    // stop the moment we arrive

            node = node.Right;
        }

        throw new ArgumentOutOfRangeException(nameof(k), "k exceeds the number of nodes");
    }

    public static void Main()
    {
        //     5
        //    / \
        //   3   6
        //  / \
        // 2   4
        //  
        var root = new TreeNode(5,
            new TreeNode(3, new TreeNode(2, new TreeNode(1), null), new TreeNode(4)),
            new TreeNode(6));

        Console.WriteLine(KthSmallest(root, 1));
        Console.WriteLine(KthSmallest(root, 3));
        Console.WriteLine(KthSmallest(root, 6));    // the largest

        Console.WriteLine(KthSmallest(new TreeNode(1), 1));

        try { KthSmallest(root, 99); }
        catch (ArgumentOutOfRangeException e) { Console.WriteLine(e.ParamName + " out of range"); }
    }
}
```

**Output**

```
1
3
6
1
k out of range
```

**Logic**

A pre-order traversal that writes an explicit marker for every null is enough to reconstruct the tree exactly. Without null markers the encoding is ambiguous, because different trees can share a traversal; with them, the structure is fully determined and deserialisation is a single recursive pass consuming tokens in the same order.

Both directions are O(n) time and O(n) space. This is the general case: for a BST alone you could omit nulls and use the ordering to rebuild, and for a complete tree an array layout would do.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Codec
{
    private const string Null = "#";

    public string Serialize(TreeNode root)
    {
        var sb = new StringBuilder();
        Write(root, sb);
        return sb.ToString().TrimEnd(',');
    }

    private void Write(TreeNode node, StringBuilder sb)
    {
        if (node == null) { sb.Append(Null).Append(','); return; }

        sb.Append(node.Val).Append(',');   // pre-order: root, then left, then right
        Write(node.Left, sb);
        Write(node.Right, sb);
    }

    public TreeNode Deserialize(string data)
    {
        if (string.IsNullOrEmpty(data)) return null;
        var tokens = new Queue<string>(data.Split(','));
        return Read(tokens);
    }

    private TreeNode Read(Queue<string> tokens)
    {
        if (tokens.Count == 0) return null;

        string token = tokens.Dequeue();
        if (token == Null) return null;

        // Same order as Write, so the tokens line up exactly.
        return new TreeNode(int.Parse(token))
        {
            Left = Read(tokens),
            Right = Read(tokens),
        };
    }
}

public class Solution
{
    public static void Main()
    {
        var codec = new Codec();

        var root = new TreeNode(1,
            new TreeNode(2),
            new TreeNode(3, new TreeNode(4), new TreeNode(5)));

        string s = codec.Serialize(root);
        Console.WriteLine(s);

        // Round-trip: serialising the rebuilt tree must give the identical string.
        Console.WriteLine(codec.Serialize(codec.Deserialize(s)) == s);

        Console.WriteLine(codec.Serialize(null));
        Console.WriteLine(codec.Serialize(codec.Deserialize(codec.Serialize(null))));

        var negative = new TreeNode(-7, new TreeNode(-8), null);
        Console.WriteLine(codec.Serialize(negative));

        var skew = new TreeNode(1, new TreeNode(2, new TreeNode(3), null), null);
        Console.WriteLine(codec.Serialize(skew));
    }
}
```

**Output**

```
1,2,#,#,3,4,#,#,5,#,#
True
#
#
-7,-8,#,#,#
1,2,3,#,#,#,#
```

**Logic**

The diameter is the longest path between any two nodes, which need not pass through the root. For each node, the longest path *through* it is the height of its left subtree plus the height of its right subtree. So compute heights bottom-up and, at every node, update a running maximum with that sum.

The key is that the recursion returns a height while the answer is tracked on the side. Trying to return the diameter directly fails, because a parent needs its children's heights, not their diameters. One post-order pass, O(n) time, O(h) space.

**Program**

```csharp
using System;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static int Diameter(TreeNode root)
    {
        int best = 0;
        Height(root, ref best);
        return best;   // measured in edges
    }

    // Returns the height of this subtree, and updates the best diameter seen.
    private static int Height(TreeNode node, ref int best)
    {
        if (node == null) return 0;

        int left = Height(node.Left, ref best);
        int right = Height(node.Right, ref best);

        // Longest path passing THROUGH this node, in edges.
        if (left + right > best) best = left + right;

        return 1 + Math.Max(left, right);   // what the parent needs
    }

    public static void Main()
    {
        //     1
        //    / \
        //   2   3
        //  / \
        // 4   5        longest: 4-2-1-3 = 3 edges
        var root = new TreeNode(1,
            new TreeNode(2, new TreeNode(4), new TreeNode(5)),
            new TreeNode(3));
        Console.WriteLine(Diameter(root));

        Console.WriteLine(Diameter(new TreeNode(1, new TreeNode(2), null)));
        Console.WriteLine(Diameter(new TreeNode(1)));
        Console.WriteLine(Diameter(null));

        // The diameter avoids the root entirely: it lies inside the left subtree.
        var skew = new TreeNode(1,
            new TreeNode(2,
                new TreeNode(4, new TreeNode(6), null),
                new TreeNode(5, null, new TreeNode(7))),
            null);
        Console.WriteLine(Diameter(skew));
    }
}
```

**Output**

```
3
1
0
0
4
```

**Logic**

Balanced means every node's two subtree heights differ by at most one. The naive version computes the height at every node and is O(n²), because heights are recomputed on the way down.

The linear version computes heights bottom-up and propagates failure. Use -1 as a sentinel meaning 'already unbalanced': as soon as a subtree reports it, every ancestor short-circuits without further work. One post-order pass, O(n) time, O(h) space.

**Program**

```csharp
using System;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static bool IsBalanced(TreeNode root) => Height(root) != -1;

    // Returns the height, or -1 meaning "a subtree below here is unbalanced".
    private static int Height(TreeNode node)
    {
        if (node == null) return 0;

        int left = Height(node.Left);
        if (left == -1) return -1;            // bail out early

        int right = Height(node.Right);
        if (right == -1) return -1;

        if (Math.Abs(left - right) > 1) return -1;

        return 1 + Math.Max(left, right);
    }

    public static void Main()
    {
        //     3
        //    / \
        //   9  20
        //     /  \
        //    15   7
        var balanced = new TreeNode(3,
            new TreeNode(9),
            new TreeNode(20, new TreeNode(15), new TreeNode(7)));
        Console.WriteLine(IsBalanced(balanced));

        //       1
        //      / \
        //     2   2
        //    / \
        //   3   3
        //  / \
        // 4   4
        var unbalanced = new TreeNode(1,
            new TreeNode(2,
                new TreeNode(3, new TreeNode(4), new TreeNode(4)),
                new TreeNode(3)),
            new TreeNode(2));
        Console.WriteLine(IsBalanced(unbalanced));

        Console.WriteLine(IsBalanced(null));
        Console.WriteLine(IsBalanced(new TreeNode(1)));

        // Height differs by exactly one: still balanced.
        Console.WriteLine(IsBalanced(new TreeNode(1, new TreeNode(2), null)));

        // Differs by two: not.
        Console.WriteLine(IsBalanced(new TreeNode(1, new TreeNode(2, new TreeNode(3), null), null)));
    }
}
```

