**Logic**

The result must be a right-leaning chain in preorder sequence, with every left pointer null. Unlike inverting a tree, the traversal order here is load-bearing: only preorder produces the required sequence.

The elegant O(1)-space solution uses the Morris idea. At each node with a left subtree, find that subtree's rightmost node, which is the last node of the left subtree in preorder, and attach the current right subtree to it. Then move the whole left subtree over to the right and clear the left pointer. Move on to the new right child and repeat.

Each edge is traversed a constant number of times, so O(n) time and O(1) space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null)
    { Val = val; Left = left; Right = right; }
}

public class Solution
{
    public static void Flatten(TreeNode root)
    {
        var node = root;

        while (node != null)
        {
            if (node.Left != null)
            {
                // The rightmost node of the left subtree is the last node of that
                // subtree in preorder, so the current right subtree hangs off it.
                var predecessor = node.Left;
                while (predecessor.Right != null) predecessor = predecessor.Right;

                predecessor.Right = node.Right;
                node.Right = node.Left;
                node.Left = null;
            }

            node = node.Right;
        }
    }

    private static string Chain(TreeNode root)
    {
        var parts = new List<string>();
        for (var n = root; n != null; n = n.Right)
        {
            if (n.Left != null) return "BROKEN: a left pointer survived";
            parts.Add(n.Val.ToString());
        }
        return parts.Count == 0 ? "(empty)" : string.Join("->", parts);
    }

    public static void Main()
    {
        //     1
        //    / \
        //   2   5
        //  / \   \
        // 3   4   6
        var root = new TreeNode(1,
            new TreeNode(2, new TreeNode(3), new TreeNode(4)),
            new TreeNode(5, null, new TreeNode(6)));
        Flatten(root);
        Console.WriteLine(Chain(root));

        var single = new TreeNode(1);
        Flatten(single);
        Console.WriteLine(Chain(single));

        Flatten(null);
        Console.WriteLine(Chain(null));

        // Left-only chain must end up entirely on the right.
        var leftOnly = new TreeNode(1, new TreeNode(2, new TreeNode(3), null), null);
        Flatten(leftOnly);
        Console.WriteLine(Chain(leftOnly));

        // Already flat: must be left unchanged.
        var flat = new TreeNode(1, null, new TreeNode(2, null, new TreeNode(3)));
        Flatten(flat);
        Console.WriteLine(Chain(flat));
    }
}
```

**Output**

```
