1
(empty)
1->2->3
1->2->3
```

**Logic**

Take the middle element as the root, then build the left subtree from the elements before it and the right subtree from those after. Because the array is sorted, the middle element is greater than everything on its left and less than everything on its right, which is exactly the BST property. Halving the range at every step keeps the two sides within one element of each other, so the result is height-balanced by construction.

O(n) time, since each element becomes exactly one node, and O(log n) stack space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TreeNode
{
    public int Val;
    public TreeNode Left, Right;
    public TreeNode(int val = 0) { Val = val; }
}

public class Solution
{
    public static TreeNode SortedArrayToBst(int[] nums) =>
        nums == null ? null : Build(nums, 0, nums.Length - 1);

    private static TreeNode Build(int[] nums, int low, int high)
    {
        if (low > high) return null;

        int mid = low + (high - low) / 2;     // overflow-safe, and picks the left middle

        return new TreeNode(nums[mid])
        {
            Left = Build(nums, low, mid - 1),
            Right = Build(nums, mid + 1, high),
        };
    }

    private static string LevelOrder(TreeNode root)
    {
        if (root == null) return "(empty)";
        var outp = new List<string>();
        var q = new Queue<TreeNode>();
        q.Enqueue(root);
        while (q.Count > 0)
        {
            var n = q.Dequeue();
            outp.Add(n.Val.ToString());
            if (n.Left != null) q.Enqueue(n.Left);
            if (n.Right != null) q.Enqueue(n.Right);
        }
        return string.Join(",", outp);
    }

    private static int Height(TreeNode n) =>
        n == null ? 0 : 1 + Math.Max(Height(n.Left), Height(n.Right));

    public static void Main()
    {
        var t = SortedArrayToBst(new[] { -10, -3, 0, 5, 9 });
        Console.WriteLine(LevelOrder(t));
        Console.WriteLine(Height(t));

        Console.WriteLine(LevelOrder(SortedArrayToBst(new[] { 1, 3 })));
        Console.WriteLine(LevelOrder(SortedArrayToBst(new[] { 7 })));
        Console.WriteLine(LevelOrder(SortedArrayToBst(new int[0])));

        // 15 elements: a perfectly balanced tree is height 4.
        var big = new int[15];
        for (int i = 0; i < 15; i++) big[i] = i;
        Console.WriteLine(Height(SortedArrayToBst(big)));
    }
}
```

