**Logic**

Same algorithm as the yes-or-no version, but record the order in which courses are removed. Kahn's algorithm produces a topological ordering directly: a course is only enqueued once every prerequisite has been taken, so the sequence of removals is always valid.

If the recorded order is shorter than the course count, a cycle prevented some courses from ever becoming ready, and the problem asks for an empty array in that case. O(V + E) time and space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int[] FindOrder(int numCourses, int[][] prerequisites)
    {
        var dependents = new List<int>[numCourses];
        var indegree = new int[numCourses];
        for (int i = 0; i < numCourses; i++) dependents[i] = new List<int>();

        foreach (var pair in prerequisites)
        {
            dependents[pair[1]].Add(pair[0]);   // must take pair[1] before pair[0]
            indegree[pair[0]]++;
        }

        var ready = new Queue<int>();
        for (int i = 0; i < numCourses; i++)
            if (indegree[i] == 0) ready.Enqueue(i);

        var order = new List<int>(numCourses);

        while (ready.Count > 0)
        {
            int course = ready.Dequeue();
            order.Add(course);                  // the removal order IS the answer

            foreach (int next in dependents[course])
                if (--indegree[next] == 0) ready.Enqueue(next);
        }

        // A short order means a cycle blocked the rest.
        return order.Count == numCourses ? order.ToArray() : Array.Empty<int>();
    }

    private static string Show(int[] a) => a.Length == 0 ? "(impossible)" : string.Join(",", a);

    public static void Main()
    {
        Console.WriteLine(Show(FindOrder(2, new[] { new[] { 1, 0 } })));
        Console.WriteLine(Show(FindOrder(4, new[] {
            new[] { 1, 0 }, new[] { 2, 0 }, new[] { 3, 1 }, new[] { 3, 2 } })));
        Console.WriteLine(Show(FindOrder(1, Array.Empty<int[]>())));
        Console.WriteLine(Show(FindOrder(2, new[] { new[] { 0, 1 }, new[] { 1, 0 } })));
        Console.WriteLine(Show(FindOrder(3, Array.Empty<int[]>())));
    }
}
