**Logic**

BFS from every rotten orange at once. Seed the queue with all initially rotten cells, then process level by level: each level is one minute, during which every currently rotten orange infects its fresh orthogonal neighbours. The answer is the number of levels processed.

Starting from all sources simultaneously is what makes this correct and linear. Running a separate BFS per source and taking minimums would be far slower and needlessly complex. At the end, any fresh orange left is unreachable, so the answer is -1.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int OrangesRotting(int[][] grid)
    {
        int rows = grid.Length, cols = grid[0].Length;
        var queue = new Queue<(int r, int c)>();
        int fresh = 0;

        // Seed with EVERY rotten orange: one BFS, many sources.
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                if (grid[r][c] == 2) queue.Enqueue((r, c));
                else if (grid[r][c] == 1) fresh++;
            }

        if (fresh == 0) return 0;      // nothing to rot: zero minutes, not -1

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };
        int minutes = 0;

        while (queue.Count > 0 && fresh > 0)
        {
            int levelSize = queue.Count;   // one level = one minute
            minutes++;

            for (int i = 0; i < levelSize; i++)
            {
                var (r, c) = queue.Dequeue();

                for (int d = 0; d < 4; d++)
                {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                    if (grid[nr][nc] != 1) continue;

                    grid[nr][nc] = 2;      // mark on enqueue
                    fresh--;
                    queue.Enqueue((nr, nc));
                }
            }
        }

        return fresh == 0 ? minutes : -1;   // leftovers were unreachable
    }

    private static int[][] Grid(params int[][] rows) => rows;

    public static void Main()
    {
        Console.WriteLine(OrangesRotting(Grid(
            new[] { 2, 1, 1 }, new[] { 1, 1, 0 }, new[] { 0, 1, 1 })));

        Console.WriteLine(OrangesRotting(Grid(
            new[] { 2, 1, 1 }, new[] { 0, 1, 1 }, new[] { 1, 0, 1 })));   // one is cut off

        Console.WriteLine(OrangesRotting(Grid(new[] { 0, 2 })));          // nothing fresh
        Console.WriteLine(OrangesRotting(Grid(new[] { 0 })));             // empty grid
        Console.WriteLine(OrangesRotting(Grid(new[] { 1 })));             // fresh, no source
        Console.WriteLine(OrangesRotting(Grid(
            new[] { 2, 2 }, new[] { 1, 1 })));                            // two sources at once
    }
}
```

