-1
0
0
-1
1
```

**Logic**

Each word is a node, and two words are adjacent when they differ by exactly one letter. The shortest transformation sequence is then the shortest path in an unweighted graph, which is BFS.

Building the edges by comparing every pair of words is O(n²·L). The better approach generates neighbours on demand: for each position in the current word, try all 26 letters and keep the candidates present in the dictionary. That is O(26·L) per word and avoids materialising the graph at all.

Removing a word from the set as soon as it is enqueued serves as the visited marker.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static int LadderLength(string begin, string end, IList<string> wordList)
    {
        var words = new HashSet<string>(wordList);
        if (!words.Contains(end)) return 0;      // unreachable by definition

        var queue = new Queue<string>();
        queue.Enqueue(begin);
        words.Remove(begin);

        int length = 1;                          // the sequence includes begin

        while (queue.Count > 0)
        {
            int levelSize = queue.Count;

            for (int i = 0; i < levelSize; i++)
            {
                string word = queue.Dequeue();
                if (word == end) return length;

                var chars = word.ToCharArray();
                for (int p = 0; p < chars.Length; p++)
                {
                    char original = chars[p];

                    for (char c = 'a'; c <= 'z'; c++)
                    {
                        if (c == original) continue;
                        chars[p] = c;

                        string candidate = new string(chars);
                        if (words.Remove(candidate))   // Remove doubles as "visit"
                            queue.Enqueue(candidate);
                    }

                    chars[p] = original;               // restore before the next position
                }
            }

            length++;
        }

        return 0;
    }

    public static void Main()
    {
        Console.WriteLine(LadderLength("hit", "cog",
            new List<string> { "hot", "dot", "dog", "lot", "log", "cog" }));

        Console.WriteLine(LadderLength("hit", "cog",
            new List<string> { "hot", "dot", "dog", "lot", "log" }));   // cog absent

        Console.WriteLine(LadderLength("a", "c", new List<string> { "a", "b", "c" }));
        Console.WriteLine(LadderLength("hot", "dog", new List<string> { "hot", "dog" }));
        Console.WriteLine(LadderLength("hot", "hot", new List<string> { "hot" }));
    }
}
```

