**Logic**

Invert the flow. Asking, for each cell, whether water can reach both oceans means running a search from every cell, which is expensive. Instead start at the oceans and walk *uphill*: from the Pacific border inward, visiting neighbours whose height is greater than or equal to the current cell, and likewise from the Atlantic border. The answer is the intersection of the two reachable sets.

That inversion turns many searches into two. O(rows × cols) time and space.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static IList<int[]> PacificAtlantic(int[][] heights)
    {
        var result = new List<int[]>();
        if (heights == null || heights.Length == 0) return result;

        int rows = heights.Length, cols = heights[0].Length;
        var pacific = new bool[rows, cols];
        var atlantic = new bool[rows, cols];

        // Pacific touches the top and left; Atlantic the bottom and right.
        for (int r = 0; r < rows; r++)
        {
            Flow(heights, pacific, r, 0);
            Flow(heights, atlantic, r, cols - 1);
        }
        for (int c = 0; c < cols; c++)
        {
            Flow(heights, pacific, 0, c);
            Flow(heights, atlantic, rows - 1, c);
        }

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (pacific[r, c] && atlantic[r, c])
                    result.Add(new[] { r, c });

        return result;
    }

    // Walks uphill from the ocean: water flows down, so reachability runs upward.
    private static void Flow(int[][] heights, bool[,] seen, int startRow, int startCol)
    {
        int rows = heights.Length, cols = heights[0].Length;
        if (seen[startRow, startCol]) return;

        var stack = new Stack<(int r, int c)>();
        seen[startRow, startCol] = true;
        stack.Push((startRow, startCol));

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (stack.Count > 0)
        {
            var (r, c) = stack.Pop();

            for (int d = 0; d < 4; d++)
            {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (seen[nr, nc]) continue;
                if (heights[nr][nc] < heights[r][c]) continue;   // cannot flow uphill downward

                seen[nr, nc] = true;
                stack.Push((nr, nc));
            }
        }
    }

    private static string Show(IList<int[]> cells)
    {
        var parts = new List<string>();
        foreach (var c in cells) parts.Add($"[{c[0]},{c[1]}]");
        parts.Sort(StringComparer.Ordinal);
        return parts.Count == 0 ? "(none)" : string.Join(" ", parts);
    }

    public static void Main()
    {
        Console.WriteLine(Show(PacificAtlantic(new[] {
            new[] { 1, 2, 2, 3, 5 },
            new[] { 3, 2, 3, 4, 4 },
            new[] { 2, 4, 5, 3, 1 },
            new[] { 6, 7, 1, 4, 5 },
            new[] { 5, 1, 1, 2, 4 } })));

        Console.WriteLine(Show(PacificAtlantic(new[] { new[] { 1 } })));

        // A flat grid: every cell reaches both oceans.
        Console.WriteLine(Show(PacificAtlantic(new[] {
            new[] { 1, 1 }, new[] { 1, 1 } })));
    }
}
```

