**Logic**

Invert the problem. Finding every enclosed region is awkward, but finding the *safe* ones is easy: an 'O' survives exactly when it connects to the border. So flood-fill inward from every 'O' on the edge, marking everything reached as safe. Then one sweep flips all remaining 'O's to 'X' and restores the marked ones.

That inversion turns a hard containment question into a simple reachability one. O(rows × cols) time, and O(1) extra space beyond the traversal if the safe marker is written into the grid itself.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static void Solve(char[][] board)
    {
        if (board == null || board.Length == 0) return;
        int rows = board.Length, cols = board[0].Length;

        // 1. Every border 'O' and everything it touches is safe: mark it 'S'.
        for (int r = 0; r < rows; r++)
        {
            MarkSafe(board, r, 0);
            MarkSafe(board, r, cols - 1);
        }
        for (int c = 0; c < cols; c++)
        {
            MarkSafe(board, 0, c);
            MarkSafe(board, rows - 1, c);
        }

        // 2. Anything still 'O' was enclosed; anything 'S' goes back to 'O'.
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                board[r][c] = board[r][c] == 'S' ? 'O' : 'X';
    }

    // Iterative flood fill: a large all-O board would overflow a recursive one.
    private static void MarkSafe(char[][] board, int startRow, int startCol)
    {
        int rows = board.Length, cols = board[0].Length;
        if (board[startRow][startCol] != 'O') return;

        var stack = new Stack<(int r, int c)>();
        board[startRow][startCol] = 'S';
        stack.Push((startRow, startCol));

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (stack.Count > 0)
        {
            var (r, c) = stack.Pop();
            for (int d = 0; d < 4; d++)
            {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (board[nr][nc] != 'O') continue;

                board[nr][nc] = 'S';
                stack.Push((nr, nc));
            }
        }
    }

    private static char[][] Parse(params string[] rows)
    {
        var g = new char[rows.Length][];
        for (int i = 0; i < rows.Length; i++) g[i] = rows[i].ToCharArray();
        return g;
    }

    private static string Render(char[][] b) =>
        string.Join("/", Array.ConvertAll(b, r => new string(r)));

    public static void Main()
    {
        var b1 = Parse("XXXX", "XOOX", "XXOX", "XOXX");
        Solve(b1);
        Console.WriteLine(Render(b1));

        var b2 = Parse("X");
        Solve(b2);
        Console.WriteLine(Render(b2));

        var b3 = Parse("OOO", "OOO", "OOO");     // all connected to the border
        Solve(b3);
        Console.WriteLine(Render(b3));

        var b4 = Parse("XXXXX", "XOOOX", "XOXOX", "XOOOX", "XXXXX");   // a ring, all enclosed
        Solve(b4);
        Console.WriteLine(Render(b4));
    }
}
