**Logic**

Greedily settle the nearest unvisited node. Keep a tentative distance for every node, start at zero for the source and infinity elsewhere, and use a min-heap keyed on distance. Pop the closest node, and for each neighbour check whether going through this node is shorter than the best known route; if so, record it and push the improved distance.

Once a node is popped it is final, because every remaining route to it must pass through something at least as far away. That argument is why the algorithm requires non-negative weights. O((V + E) log V) with a binary heap.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    // graph[u] = list of (neighbour, weight)
    public static int[] Dijkstra(List<(int to, int weight)>[] graph, int source)
    {
        int n = graph.Length;
        var dist = new int[n];
        Array.Fill(dist, int.MaxValue);
        dist[source] = 0;

        var heap = new PriorityQueue<int, int>();
        heap.Enqueue(source, 0);

        var settled = new bool[n];

        while (heap.Count > 0)
        {
            int node = heap.Dequeue();

            // A node can be pushed several times with improving distances; the
            // first pop is the final one, so ignore the stale copies.
            if (settled[node]) continue;
            settled[node] = true;

            foreach (var (next, weight) in graph[node])
            {
                if (dist[node] == int.MaxValue) continue;

                int candidate = dist[node] + weight;
                if (candidate < dist[next])
                {
                    dist[next] = candidate;
                    heap.Enqueue(next, candidate);
                }
            }
        }

        return dist;
    }

    private static string Show(int[] d) =>
        string.Join(",", Array.ConvertAll(d, x => x == int.MaxValue ? "inf" : x.ToString()));

    public static void Main()
    {
        //      (4)
        //  0 -------- 1
        //  | \        |
        // (1)  (8)   (2)
        //  |      \   |
        //  2 ------- 3
        //      (1)
        var g = new List<(int, int)>[4];
        for (int i = 0; i < 4; i++) g[i] = new List<(int, int)>();
        void Edge(int a, int b, int w) { g[a].Add((b, w)); g[b].Add((a, w)); }

        Edge(0, 1, 4);
        Edge(0, 2, 1);
        Edge(0, 3, 8);
        Edge(2, 3, 1);
        Edge(1, 3, 2);

        Console.WriteLine(Show(Dijkstra(g, 0)));

        // A disconnected node stays at infinity.
        var d = new List<(int, int)>[3];
        for (int i = 0; i < 3; i++) d[i] = new List<(int, int)>();
        d[0].Add((1, 5)); d[1].Add((0, 5));
        Console.WriteLine(Show(Dijkstra(d, 0)));

        var single = new List<(int, int)>[1] { new() };
        Console.WriteLine(Show(Dijkstra(single, 0)));
    }
}
```

