**Logic**

Process edges one at a time. For each edge, find the representative of both endpoints: if they already share one, the two nodes were already connected, so this edge closes a cycle. Otherwise union them.

The subtlety specific to undirected graphs is that an edge is not a cycle just because you can walk back along it. Union-find sidesteps that entirely, since it reasons about set membership rather than about traversal paths. Near-linear time with path compression and union by rank.

**Program**

```csharp
using System;

public class Solution
{
    public static bool HasCycle(int n, int[][] edges)
    {
        var parent = new int[n];
        var rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int Find(int x)
        {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;
        }

        foreach (var e in edges)
        {
            int a = Find(e[0]), b = Find(e[1]);

            // Already in the same set: this edge closes a loop.
            if (a == b) return true;

            if (rank[a] < rank[b]) (a, b) = (b, a);
            parent[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
        }

        return false;
    }

    public static void Main()
    {
        Console.WriteLine(HasCycle(3, new[] {
            new[] { 0, 1 }, new[] { 1, 2 }, new[] { 2, 0 } }));      // triangle

        Console.WriteLine(HasCycle(3, new[] {
            new[] { 0, 1 }, new[] { 1, 2 } }));                      // a path

        Console.WriteLine(HasCycle(4, new[] {
            new[] { 0, 1 }, new[] { 2, 3 } }));                      // two separate edges

        Console.WriteLine(HasCycle(2, new[] {
            new[] { 0, 1 }, new[] { 0, 1 } }));                      // parallel edge counts

        Console.WriteLine(HasCycle(1, Array.Empty<int[]>()));
        Console.WriteLine(HasCycle(5, new[] {
            new[] { 0, 1 }, new[] { 1, 2 }, new[] { 3, 4 }, new[] { 4, 3 } }));
    }
}
```

