**Logic**

Two standard answers. Traverse from every unvisited node, marking everything reachable, and count how many traversals were needed; each one consumes exactly one component. That is O(V + E).

Or use union-find: start with V components, union the endpoints of every edge, and decrement the count each time a union actually merges two distinct sets. That is near-linear and has the advantage of working incrementally as edges arrive, which traversal cannot do without starting over.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    // Traversal: one DFS per component.
    public static int CountComponents(int n, int[][] edges)
    {
        var adj = new List<int>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int>();
        foreach (var e in edges) { adj[e[0]].Add(e[1]); adj[e[1]].Add(e[0]); }

        var seen = new bool[n];
        int components = 0;

        for (int start = 0; start < n; start++)
        {
            if (seen[start]) continue;
            components++;

            var stack = new Stack<int>();
            stack.Push(start);
            seen[start] = true;

            while (stack.Count > 0)
                foreach (int next in adj[stack.Pop()])
                    if (!seen[next]) { seen[next] = true; stack.Push(next); }
        }

        return components;
    }

    // Union-find: start at n components, merge on each effective union.
    public static int CountComponentsUnionFind(int n, int[][] edges)
    {
        var parent = new int[n];
        var rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int Find(int x)
        {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;   // path halving keeps trees flat
        }

        int components = n;
        foreach (var e in edges)
        {
            int a = Find(e[0]), b = Find(e[1]);
            if (a == b) continue;                  // already together

            if (rank[a] < rank[b]) (a, b) = (b, a);
            parent[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
            components--;
        }

        return components;
    }

    public static void Main()
    {
        var e1 = new[] { new[] { 0, 1 }, new[] { 1, 2 }, new[] { 3, 4 } };
        Console.WriteLine(CountComponents(5, e1));
        Console.WriteLine(CountComponentsUnionFind(5, e1));

        var e2 = new[] { new[] { 0, 1 }, new[] { 1, 2 }, new[] { 2, 3 }, new[] { 3, 4 } };
        Console.WriteLine(CountComponents(5, e2));

        Console.WriteLine(CountComponents(4, Array.Empty<int[]>()));   // no edges at all
        Console.WriteLine(CountComponents(1, Array.Empty<int[]>()));
        Console.WriteLine(CountComponentsUnionFind(3, new[] {
            new[] { 0, 1 }, new[] { 0, 1 } }));                        // duplicate edge
    }
}
```

