1
2
```

**Logic**

A graph on n nodes is a tree exactly when it is connected and has no cycle. Those two conditions together force the edge count to be n-1, and conversely, given n-1 edges, connected implies acyclic and acyclic implies connected. So the cheapest correct test is: check the edge count is n-1, then check either one of the two properties.

Checking the edge count first is worth doing because it rejects most invalid inputs in constant time, and it means the subsequent union-find pass only has to establish connectivity.

**Program**

```csharp
using System;

public class Solution
{
    public static bool ValidTree(int n, int[][] edges)
    {
        // A tree on n nodes has exactly n-1 edges. Too few cannot connect, too
        // many must contain a cycle. This one line removes most bad inputs.
        if (edges.Length != n - 1) return false;

        var parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int Find(int x)
        {
            while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
            return x;
        }

        foreach (var e in edges)
        {
            int a = Find(e[0]), b = Find(e[1]);
            if (a == b) return false;    // a cycle, so with n-1 edges it cannot be connected
            parent[b] = a;
        }

        // n-1 edges and no cycle means exactly one component.
        return true;
    }

    public static void Main()
    {
        Console.WriteLine(ValidTree(5, new[] {
            new[] { 0, 1 }, new[] { 0, 2 }, new[] { 0, 3 }, new[] { 1, 4 } }));

        Console.WriteLine(ValidTree(5, new[] {
            new[] { 0, 1 }, new[] { 1, 2 }, new[] { 2, 3 }, new[] { 1, 3 }, new[] { 1, 4 } }));

        Console.WriteLine(ValidTree(4, new[] {
            new[] { 0, 1 }, new[] { 2, 3 } }));       // two components, too few edges

        Console.WriteLine(ValidTree(1, Array.Empty<int[]>()));   // single node is a tree
        Console.WriteLine(ValidTree(2, Array.Empty<int[]>()));   // disconnected

        Console.WriteLine(ValidTree(3, new[] {
            new[] { 0, 1 }, new[] { 0, 1 } }));       // right count, but a parallel edge
    }
}
