**Logic**

A graph is bipartite when its nodes can be split into two sets with every edge crossing between them, which is the same as saying it is two-colourable. Traverse, colouring each node the opposite of the node you arrived from. If you ever meet an already-coloured neighbour with the same colour as the current node, an edge lies inside a set and the graph is not bipartite.

The graph may be disconnected, so the traversal must be started from every uncoloured node. O(V + E).

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    public static bool IsBipartite(int[][] graph)
    {
        int n = graph.Length;
        var colour = new int[n];     // 0 = uncoloured, 1 and -1 are the two sides

        for (int start = 0; start < n; start++)
        {
            if (colour[start] != 0) continue;   // components must each be checked

            var queue = new Queue<int>();
            colour[start] = 1;
            queue.Enqueue(start);

            while (queue.Count > 0)
            {
                int node = queue.Dequeue();

                foreach (int next in graph[node])
                {
                    if (colour[next] == colour[node]) return false;   // same side: not bipartite

                    if (colour[next] == 0)
                    {
                        colour[next] = -colour[node];
                        queue.Enqueue(next);
                    }
                }
            }
        }

        return true;
    }

    public static void Main()
    {
        // A square: 0-1-2-3-0, an even cycle, so bipartite.
        Console.WriteLine(IsBipartite(new[] {
            new[] { 1, 3 }, new[] { 0, 2 }, new[] { 1, 3 }, new[] { 0, 2 } }));

        // A triangle: an odd cycle, so not.
        Console.WriteLine(IsBipartite(new[] {
            new[] { 1, 2 }, new[] { 0, 2 }, new[] { 0, 1 } }));

        Console.WriteLine(IsBipartite(new[] { Array.Empty<int>() }));       // one lonely node

        // Two components, one bipartite and one not.
        Console.WriteLine(IsBipartite(new[] {
            new[] { 1 }, new[] { 0 },
            new[] { 3, 4 }, new[] { 2, 4 }, new[] { 2, 3 } }));

        // A path of four nodes.
        Console.WriteLine(IsBipartite(new[] {
            new[] { 1 }, new[] { 0, 2 }, new[] { 1, 3 }, new[] { 2 } }));
    }
}
```

