False
True
False
True
```

**Logic**

Each node holds links to child nodes, one per possible next character, plus a flag marking whether a complete word ends there. Walking a word means following one link per character. Insert creates missing links; search walks and checks the end-of-word flag; startsWith walks and only checks that the path exists.

The end-of-word flag is what separates the two lookups: without it, searching for "app" in a trie containing only "apple" would wrongly succeed. All three operations are O(length of the key), independent of how many words the trie holds.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Trie
{
    private sealed class Node
    {
        public readonly Dictionary<char, Node> Children = new();
        public bool IsWord;      // distinguishes a stored word from a mere prefix
    }

    private readonly Node _root = new();

    public void Insert(string word)
    {
        var node = _root;
        foreach (char c in word)
        {
            if (!node.Children.TryGetValue(c, out var next))
                node.Children[c] = next = new Node();
            node = next;
        }
        node.IsWord = true;
    }

    public bool Search(string word)
    {
        var node = Walk(word);
        return node != null && node.IsWord;      // must be a complete word
    }

    public bool StartsWith(string prefix) => Walk(prefix) != null;

    private Node Walk(string s)
    {
        var node = _root;
        foreach (char c in s)
        {
            if (!node.Children.TryGetValue(c, out node)) return null;
        }
        return node;
    }

    // Everything stored under a prefix - the reason a trie exists.
    public IEnumerable<string> WithPrefix(string prefix)
    {
        var start = Walk(prefix);
        if (start == null) yield break;

        var stack = new Stack<(Node node, string text)>();
        stack.Push((start, prefix));

        while (stack.Count > 0)
        {
            var (node, text) = stack.Pop();
            if (node.IsWord) yield return text;
            foreach (var (c, child) in node.Children) stack.Push((child, text + c));
        }
    }
}

public class Solution
{
    public static void Main()
    {
        var trie = new Trie();
        trie.Insert("apple");

        Console.WriteLine(trie.Search("apple"));
        Console.WriteLine(trie.Search("app"));        // a prefix, not a stored word
        Console.WriteLine(trie.StartsWith("app"));

        trie.Insert("app");
        Console.WriteLine(trie.Search("app"));        // now it is

        Console.WriteLine(trie.Search("apples"));     // walks off the end
        Console.WriteLine(trie.StartsWith("b"));

        trie.Insert("application");
        var found = new List<string>(trie.WithPrefix("app"));
        found.Sort();
        Console.WriteLine(string.Join(",", found));
    }
}
