**Logic**

To arrive at step n you came either from n-1 with a single step or from n-2 with a double step, so `ways(n) = ways(n-1) + ways(n-2)`. That is the Fibonacci recurrence with `ways(1) = 1` and `ways(2) = 2`.

The naive recursion recomputes the same subproblems exponentially, at roughly O(2^n). Since each value depends only on the previous two, you do not need an array at all: two rolling variables give O(n) time and O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static long ClimbStairs(int n)
    {
        if (n <= 0) return 0;
        if (n <= 2) return n;          // 1 step -> 1 way, 2 steps -> 2 ways

        long prev = 1, current = 2;    // ways(1), ways(2)

        for (int i = 3; i <= n; i++)
        {
            long next = prev + current;
            prev = current;
            current = next;
        }

        return current;
    }

    // Generalised: any set of allowed step sizes. Same recurrence, summed over
    // every step that could have been the last one taken.
    public static long ClimbStairs(int n, int[] steps)
    {
        var ways = new long[n + 1];
        ways[0] = 1;                   // one way to stand at the bottom: do nothing

        for (int i = 1; i <= n; i++)
            foreach (int s in steps)
                if (i - s >= 0) ways[i] += ways[i - s];

        return ways[n];
    }

    public static void Main()
    {
        Console.WriteLine(ClimbStairs(2));
        Console.WriteLine(ClimbStairs(3));
        Console.WriteLine(ClimbStairs(5));
        Console.WriteLine(ClimbStairs(45));
        Console.WriteLine(ClimbStairs(0));
        Console.WriteLine(ClimbStairs(7, new[] { 1, 2, 3 }));   // with triple steps too
    }
}
```

