**Logic**

At each house there are two choices: rob it and add its value to the best total from two houses back, or skip it and keep the best total from the previous house. So `best[i] = max(best[i-1], best[i-2] + nums[i])`.

Because each value depends only on the previous two, no array is needed: two rolling variables give O(n) time and O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int Rob(int[] nums)
    {
        if (nums == null || nums.Length == 0) return 0;

        int twoBack = 0;   // best total up to i-2
        int oneBack = 0;   // best total up to i-1

        foreach (int value in nums)
        {
            // Rob this house (value + twoBack) or skip it (oneBack).
            int current = Math.Max(oneBack, twoBack + value);
            twoBack = oneBack;
            oneBack = current;
        }

        return oneBack;
    }

    // Houses in a circle: the first and last are now adjacent, so the answer is
    // the better of "skip the last" and "skip the first".
    public static int RobCircular(int[] nums)
    {
        if (nums == null || nums.Length == 0) return 0;
        if (nums.Length == 1) return nums[0];

        return Math.Max(Rob(nums[..^1]), Rob(nums[1..]));
    }

    public static void Main()
    {
        Console.WriteLine(Rob(new[] { 1, 2, 3, 1 }));        // 1 + 3
        Console.WriteLine(Rob(new[] { 2, 7, 9, 3, 1 }));      // 2 + 9 + 1
        Console.WriteLine(Rob(new[] { 5 }));
        Console.WriteLine(Rob(new int[0]));
        Console.WriteLine(Rob(new[] { 2, 1, 1, 2 }));         // 2 + 2, skipping two in a row
        Console.WriteLine(RobCircular(new[] { 2, 3, 2 }));    // cannot take both 2s
    }
}
```

