9
0
1
1
4
```

The first two lines are the same input giving different answers, which is the whole lesson: 4 combinations, 9 permutations.

**Logic**

The O(n²) dynamic programme sets `best[i]` to the longest increasing subsequence ending at index i, found by scanning every earlier smaller element. Simple and easy to justify.

The O(n log n) version keeps a `tails` array where `tails[k]` is the smallest possible tail value of an increasing subsequence of length k+1. For each number, binary search for the first tail that is greater than or equal to it and overwrite it, or append if it exceeds every tail. The length of `tails` is the answer.

Note that `tails` is not itself a valid subsequence; only its length is meaningful.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    // O(n log n): tails[k] = smallest tail of any increasing subsequence of length k+1.
    public static int LengthOfLis(int[] nums)
    {
        if (nums == null || nums.Length == 0) return 0;

        var tails = new List<int>();

        foreach (int n in nums)
        {
            int position = LowerBound(tails, n);

            if (position == tails.Count) tails.Add(n);   // extends the longest run
            else tails[position] = n;                    // a smaller tail for that length
        }

        return tails.Count;
    }

    // First index whose value is >= target.
    private static int LowerBound(List<int> list, int target)
    {
        int low = 0, high = list.Count;
        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (list[mid] < target) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    // O(n^2): easier to justify, and the version that extends to reconstruction.
    public static int LengthOfLisQuadratic(int[] nums)
    {
        if (nums == null || nums.Length == 0) return 0;

        var best = new int[nums.Length];
        Array.Fill(best, 1);
        int answer = 1;

        for (int i = 1; i < nums.Length; i++)
            for (int j = 0; j < i; j++)
                if (nums[j] < nums[i] && best[j] + 1 > best[i])
                {
                    best[i] = best[j] + 1;
                    if (best[i] > answer) answer = best[i];
                }

        return answer;
    }

    public static void Main()
    {
        int[] a = { 10, 9, 2, 5, 3, 7, 101, 18 };
        Console.WriteLine(LengthOfLis(a));
        Console.WriteLine(LengthOfLisQuadratic(a));

        Console.WriteLine(LengthOfLis(new[] { 0, 1, 0, 3, 2, 3 }));
        Console.WriteLine(LengthOfLis(new[] { 7, 7, 7, 7 }));     // strictly increasing only
        Console.WriteLine(LengthOfLis(new[] { 5 }));
        Console.WriteLine(LengthOfLis(new int[0]));
        Console.WriteLine(LengthOfLis(new[] { 4, 3, 2, 1 }));
    }
}
```

