**Logic**

A two-dimensional table where `best[i][j]` is the LCS length of the first i characters of one string and the first j of the other. If the characters match, the answer extends the diagonal by one. If they do not, it is the better of dropping one character from either string.

O(m·n) time and space, reducible to O(min(m,n)) space by keeping only the previous row, since each cell looks only at the row above and the cell to its left.

**Program**

```csharp
using System;
using System.Text;

public class Solution
{
    public static int LongestCommonSubsequence(string a, string b)
    {
        if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b)) return 0;

        var best = new int[a.Length + 1, b.Length + 1];   // row/col 0 = empty prefix

        for (int i = 1; i <= a.Length; i++)
            for (int j = 1; j <= b.Length; j++)
                best[i, j] = a[i - 1] == b[j - 1]
                    ? best[i - 1, j - 1] + 1                          // match: extend diagonal
                    : Math.Max(best[i - 1, j], best[i, j - 1]);       // drop one character

        return best[a.Length, b.Length];
    }

    // Walk the table backwards to recover the subsequence itself.
    public static string LcsString(string a, string b)
    {
        var best = new int[a.Length + 1, b.Length + 1];
        for (int i = 1; i <= a.Length; i++)
            for (int j = 1; j <= b.Length; j++)
                best[i, j] = a[i - 1] == b[j - 1]
                    ? best[i - 1, j - 1] + 1
                    : Math.Max(best[i - 1, j], best[i, j - 1]);

        var sb = new StringBuilder();
        int x = a.Length, y = b.Length;
        while (x > 0 && y > 0)
        {
            if (a[x - 1] == b[y - 1]) { sb.Insert(0, a[x - 1]); x--; y--; }
            else if (best[x - 1, y] >= best[x, y - 1]) x--;
            else y--;
        }
        return sb.ToString();
    }

    public static void Main()
    {
        Console.WriteLine(LongestCommonSubsequence("abcde", "ace"));
        Console.WriteLine(LcsString("abcde", "ace"));

        Console.WriteLine(LongestCommonSubsequence("abc", "abc"));
        Console.WriteLine(LongestCommonSubsequence("abc", "def"));
        Console.WriteLine(LongestCommonSubsequence("", "abc"));
        Console.WriteLine(LcsString("AGGTAB", "GXTXAYB"));
    }
}
```

