**Logic**

`best[i][j]` is the fewest single-character edits turning the first i characters of one string into the first j of the other. If the current characters match, nothing is spent and the answer is the diagonal. Otherwise it is one plus the cheapest of three moves: delete (cell above), insert (cell to the left), or replace (diagonal).

The base row and column are the costs of building a string from nothing, which is one insert per character. O(m·n) time and space.

**Program**

```csharp
using System;

public class Solution
{
    public static int MinDistance(string a, string b)
    {
        a ??= ""; b ??= "";
        var best = new int[a.Length + 1, b.Length + 1];

        // Turning a prefix into the empty string costs one delete per character.
        for (int i = 0; i <= a.Length; i++) best[i, 0] = i;
        for (int j = 0; j <= b.Length; j++) best[0, j] = j;

        for (int i = 1; i <= a.Length; i++)
            for (int j = 1; j <= b.Length; j++)
            {
                if (a[i - 1] == b[j - 1])
                {
                    best[i, j] = best[i - 1, j - 1];        // free
                }
                else
                {
                    int delete = best[i - 1, j];
                    int insert = best[i, j - 1];
                    int replace = best[i - 1, j - 1];
                    best[i, j] = 1 + Math.Min(replace, Math.Min(delete, insert));
                }
            }

        return best[a.Length, b.Length];
    }

    public static void Main()
    {
        Console.WriteLine(MinDistance("horse", "ros"));
        Console.WriteLine(MinDistance("intention", "execution"));
        Console.WriteLine(MinDistance("", "abc"));        // three inserts
        Console.WriteLine(MinDistance("abc", ""));        // three deletes
        Console.WriteLine(MinDistance("same", "same"));
        Console.WriteLine(MinDistance("a", "b"));         // one replace
    }
}
```

