```
True
False
True
True
False
True
```

**Logic**

Every cell is reachable only from above or from the left, so the number of paths to a cell is the sum of those two. The top row and left column have exactly one path each, since there is only one way to walk straight along an edge.

That gives an O(m·n) table, reducible to a single row because each value needs only the cell above (the row's previous value) and the cell to the left (the value just computed).

There is also a closed form: the path is a sequence of (m-1) downs and (n-1) rights in some order, so the count is the binomial coefficient C(m+n-2, m-1).

**Program**

```csharp
using System;

public class Solution
{
    // One row of DP: O(n) space.
    public static long UniquePaths(int m, int n)
    {
        if (m <= 0 || n <= 0) return 0;

        var row = new long[n];
        Array.Fill(row, 1);           // the top row: one path to each cell

        for (int r = 1; r < m; r++)
            for (int c = 1; c < n; c++)
                row[c] += row[c - 1];  // above (old value) + left (just updated)

        return row[n - 1];
    }

    // Closed form: choose which of the m+n-2 moves are downs.
    public static long UniquePathsFormula(int m, int n)
    {
        long result = 1;
        int moves = m + n - 2, choose = Math.Min(m, n) - 1;

        // Multiply then divide each step to keep the running value exact and small.
        for (int i = 1; i <= choose; i++)
            result = result * (moves - choose + i) / i;

        return result;
    }

    // With obstacles: a blocked cell simply has zero paths through it.
    public static long UniquePathsWithObstacles(int[][] grid)
    {
        int rows = grid.Length, cols = grid[0].Length;
        var row = new long[cols];
        row[0] = grid[0][0] == 1 ? 0 : 1;

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
            {
                if (grid[r][c] == 1) row[c] = 0;        // unreachable
                else if (c > 0) row[c] += row[c - 1];
            }

        return row[cols - 1];
    }

    public static void Main()
    {
        Console.WriteLine(UniquePaths(3, 7));
        Console.WriteLine(UniquePathsFormula(3, 7));
        Console.WriteLine(UniquePaths(3, 2));
        Console.WriteLine(UniquePaths(1, 1));
        Console.WriteLine(UniquePaths(10, 10));

        Console.WriteLine(UniquePathsWithObstacles(new[] {
            new[] { 0, 0, 0 }, new[] { 0, 1, 0 }, new[] { 0, 0, 0 } }));
    }
}
```

