**Logic**

Same shape as counting paths, but minimising a cost instead of summing counts. The cheapest way to reach a cell is its own value plus the cheaper of the cells above and to the left. The first row and column have only one predecessor each, so they are running totals.

O(rows × cols) time, and O(cols) space with a single rolling row.

**Program**

```csharp
using System;

public class Solution
{
    public static int MinPathSum(int[][] grid)
    {
        if (grid == null || grid.Length == 0) return 0;

        int rows = grid.Length, cols = grid[0].Length;
        var row = new int[cols];

        // First row: the only way in is from the left.
        row[0] = grid[0][0];
        for (int c = 1; c < cols; c++) row[c] = row[c - 1] + grid[0][c];

        for (int r = 1; r < rows; r++)
        {
            row[0] += grid[r][0];                       // first column: only from above

            for (int c = 1; c < cols; c++)
                row[c] = grid[r][c] + Math.Min(row[c],   // above (not yet overwritten)
                                               row[c - 1]); // left (already updated)
        }

        return row[cols - 1];
    }

    public static void Main()
    {
        Console.WriteLine(MinPathSum(new[] {
            new[] { 1, 3, 1 },
            new[] { 1, 5, 1 },
            new[] { 4, 2, 1 } }));      // 1+3+1+1+1

        Console.WriteLine(MinPathSum(new[] {
            new[] { 1, 2, 3 },
            new[] { 4, 5, 6 } }));      // 1+2+3+6

        Console.WriteLine(MinPathSum(new[] { new[] { 5 } }));
        Console.WriteLine(MinPathSum(new[] { new[] { 1, 2, 5 } }));   // single row
        Console.WriteLine(MinPathSum(new[] { new[] { 1 }, new[] { 2 }, new[] { 3 } }));
    }
}
```

