**Logic**

`side[r][c]` is the side length of the largest square whose bottom-right corner is at that cell. A cell holding 1 can extend a square only as far as its three neighbours allow, so the value is one plus the minimum of the cells above, to the left, and diagonally above-left. A cell holding 0 is zero.

The minimum is the crux: a square needs all three directions to support it, so the weakest one caps it. Track the largest side seen and return its square. O(rows × cols) time, and O(cols) space with a rolling row.

**Program**

```csharp
using System;

public class Solution
{
    public static int MaximalSquare(char[][] matrix)
    {
        if (matrix == null || matrix.Length == 0) return 0;

        int rows = matrix.Length, cols = matrix[0].Length;
        var side = new int[rows + 1, cols + 1];   // padded, so no boundary checks
        int best = 0;

        for (int r = 1; r <= rows; r++)
            for (int c = 1; c <= cols; c++)
            {
                if (matrix[r - 1][c - 1] != '1') continue;

                // All three neighbours must support the square; the smallest caps it.
                side[r, c] = 1 + Math.Min(side[r - 1, c],
                                 Math.Min(side[r, c - 1], side[r - 1, c - 1]));

                if (side[r, c] > best) best = side[r, c];
            }

        return best * best;      // the question asks for area, not side
    }

    private static char[][] Parse(params string[] rows)
    {
        var g = new char[rows.Length][];
        for (int i = 0; i < rows.Length; i++) g[i] = rows[i].ToCharArray();
        return g;
    }

    public static void Main()
    {
        Console.WriteLine(MaximalSquare(Parse(
            "10100",
            "10111",
            "11111",
            "10010")));

        Console.WriteLine(MaximalSquare(Parse("01", "10")));
        Console.WriteLine(MaximalSquare(Parse("0")));
        Console.WriteLine(MaximalSquare(Parse("1")));
        Console.WriteLine(MaximalSquare(Parse("111", "111", "111")));
        Console.WriteLine(MaximalSquare(Parse("1111")));      // a single row caps at 1
    }
}
```

