**Logic**

Every element is either in a subset or not, so there are 2^n subsets. Two standard ways to enumerate them.

Backtracking: walk the array, and at each index either include the element and recurse, or skip it and recurse, recording the current selection at every node of the recursion tree.

Bitmask: treat the numbers 0 to 2^n - 1 as membership masks, where bit i set means element i is included. That is iterative, allocation-light, and often clearer, though it caps out around 30 elements.

Either way the output size is exponential, so O(n·2^n) is optimal.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static IList<IList<int>> Subsets(int[] nums)
    {
        var result = new List<IList<int>>();
        Backtrack(nums, 0, new List<int>(), result);
        return result;
    }

    private static void Backtrack(int[] nums, int index, List<int> current, IList<IList<int>> result)
    {
        // Every node of the recursion tree is itself a valid subset.
        result.Add(new List<int>(current));      // copy: current keeps mutating

        for (int i = index; i < nums.Length; i++)
        {
            current.Add(nums[i]);
            Backtrack(nums, i + 1, current, result);
            current.RemoveAt(current.Count - 1);  // undo, the essence of backtracking
        }
    }

    // Bitmask: bit i of the mask means "element i is in this subset".
    public static IList<IList<int>> SubsetsBitmask(int[] nums)
    {
        var result = new List<IList<int>>();

        for (int mask = 0; mask < (1 << nums.Length); mask++)
        {
            var subset = new List<int>();
            for (int i = 0; i < nums.Length; i++)
                if ((mask & (1 << i)) != 0) subset.Add(nums[i]);
            result.Add(subset);
        }

        return result;
    }

    private static string Render(IList<IList<int>> r) =>
        string.Join(" ", r.Select(s => "[" + string.Join(",", s) + "]"));

    public static void Main()
    {
        Console.WriteLine(Render(Subsets(new[] { 1, 2, 3 })));
        Console.WriteLine(Render(SubsetsBitmask(new[] { 1, 2, 3 })));
        Console.WriteLine(Render(Subsets(new[] { 0 })));
        Console.WriteLine(Render(Subsets(new int[0])));
        Console.WriteLine(Subsets(new[] { 1, 2, 3, 4, 5 }).Count);
    }
}
```

