**Logic**

At each depth choose which unused element comes next, recurse, then undo the choice. There are n! permutations and each costs O(n) to record, so O(n·n!) is optimal.

Two common shapes. A `used` flag array preserves the original order of the input, which matters when the output is expected in lexicographic order for sorted input. Swapping elements in place avoids the extra array and is slightly faster, but scrambles the order and makes duplicate handling harder.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static IList<IList<int>> Permute(int[] nums)
    {
        var result = new List<IList<int>>();
        Backtrack(nums, new bool[nums.Length], new List<int>(), result);
        return result;
    }

    private static void Backtrack(int[] nums, bool[] used, List<int> current, IList<IList<int>> result)
    {
        if (current.Count == nums.Length)
        {
            result.Add(new List<int>(current));    // snapshot, not the live list
            return;
        }

        for (int i = 0; i < nums.Length; i++)
        {
            if (used[i]) continue;

            used[i] = true;
            current.Add(nums[i]);

            Backtrack(nums, used, current, result);

            current.RemoveAt(current.Count - 1);   // undo both parts of the choice
            used[i] = false;
        }
    }

    // With duplicates: sort, then skip a repeat whose identical predecessor is
    // not currently used, which would produce the same permutation again.
    public static IList<IList<int>> PermuteUnique(int[] nums)
    {
        Array.Sort(nums);
        var result = new List<IList<int>>();
        BacktrackUnique(nums, new bool[nums.Length], new List<int>(), result);
        return result;
    }

    private static void BacktrackUnique(int[] nums, bool[] used, List<int> current, IList<IList<int>> result)
    {
        if (current.Count == nums.Length) { result.Add(new List<int>(current)); return; }

        for (int i = 0; i < nums.Length; i++)
        {
            if (used[i]) continue;
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;

            used[i] = true;
            current.Add(nums[i]);
            BacktrackUnique(nums, used, current, result);
            current.RemoveAt(current.Count - 1);
            used[i] = false;
        }
    }

    private static string Render(IList<IList<int>> r) =>
        string.Join(" ", r.Select(s => "[" + string.Join(",", s) + "]"));

    public static void Main()
    {
        Console.WriteLine(Render(Permute(new[] { 1, 2, 3 })));
        Console.WriteLine(Render(Permute(new[] { 0, 1 })));
        Console.WriteLine(Render(Permute(new[] { 1 })));
        Console.WriteLine(Render(PermuteUnique(new[] { 1, 1, 2 })));
        Console.WriteLine(Permute(new[] { 1, 2, 3, 4 }).Count);
    }
}
```

