**Logic**

Backtracking with one crucial detail: when recursing, pass the *same* index rather than the next one, which is what allows a candidate to be reused. Passing `i + 1` would give the each-used-once variant.

Sorting the candidates enables a strong prune: once the running total plus the current candidate exceeds the target, every later candidate is larger too, so the loop can break rather than continue. That turns a lot of dead exploration into an early exit.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static IList<IList<int>> CombinationSum(int[] candidates, int target)
    {
        Array.Sort(candidates);          // enables the break below
        var result = new List<IList<int>>();
        Backtrack(candidates, target, 0, new List<int>(), result);
        return result;
    }

    private static void Backtrack(int[] candidates, int remaining, int start,
                                  List<int> current, IList<IList<int>> result)
    {
        if (remaining == 0)
        {
            result.Add(new List<int>(current));
            return;
        }

        for (int i = start; i < candidates.Length; i++)
        {
            // Sorted, so if this one overshoots, so does every later one.
            if (candidates[i] > remaining) break;

            current.Add(candidates[i]);

            // i, not i + 1: the same candidate may be used again.
            Backtrack(candidates, remaining - candidates[i], i, current, result);

            current.RemoveAt(current.Count - 1);
        }
    }

    private static string Render(IList<IList<int>> r) =>
        r.Count == 0 ? "(none)" : string.Join(" ", r.Select(s => "[" + string.Join(",", s) + "]"));

    public static void Main()
    {
        Console.WriteLine(Render(CombinationSum(new[] { 2, 3, 6, 7 }, 7)));
        Console.WriteLine(Render(CombinationSum(new[] { 2, 3, 5 }, 8)));
        Console.WriteLine(Render(CombinationSum(new[] { 2 }, 1)));       // impossible
        Console.WriteLine(Render(CombinationSum(new[] { 7 }, 7)));
        Console.WriteLine(Render(CombinationSum(new[] { 2, 4 }, 6)));
    }
}
```

