**Logic**

One queen per row, so the search picks a column for each row in turn and recurses. A placement is legal when its column, its descending diagonal and its ascending diagonal are all unoccupied.

The key to making it fast is O(1) conflict checking with three boolean sets rather than scanning the board. Both diagonals have a constant identity along their length: `row - col` is fixed on one and `row + col` on the other. Offsetting `row - col` by n keeps the index non-negative.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    public static IList<IList<string>> SolveNQueens(int n)
    {
        var result = new List<IList<string>>();
        if (n <= 0) return result;

        var columns = new bool[n];
        var descending = new bool[2 * n];   // indexed by row - col + n
        var ascending = new bool[2 * n];    // indexed by row + col
        var placement = new int[n];         // placement[row] = column

        Backtrack(0, n, columns, descending, ascending, placement, result);
        return result;
    }

    private static void Backtrack(int row, int n, bool[] columns, bool[] descending,
                                  bool[] ascending, int[] placement, IList<IList<string>> result)
    {
        if (row == n)
        {
            result.Add(Render(placement, n));
            return;
        }

        for (int col = 0; col < n; col++)
        {
            int d = row - col + n, a = row + col;

            if (columns[col] || descending[d] || ascending[a]) continue;

            columns[col] = descending[d] = ascending[a] = true;
            placement[row] = col;

            Backtrack(row + 1, n, columns, descending, ascending, placement, result);

            columns[col] = descending[d] = ascending[a] = false;   // undo
        }
    }

    private static IList<string> Render(int[] placement, int n)
    {
        var board = new List<string>(n);
        for (int r = 0; r < n; r++)
        {
            var sb = new StringBuilder(new string('.', n));
            sb[placement[r]] = 'Q';
            board.Add(sb.ToString());
        }
        return board;
    }

    public static void Main()
    {
        var four = SolveNQueens(4);
        Console.WriteLine(four.Count);
        Console.WriteLine(string.Join(" | ", four[0]));

        Console.WriteLine(SolveNQueens(1).Count);
        Console.WriteLine(SolveNQueens(2).Count);   // impossible
        Console.WriteLine(SolveNQueens(3).Count);   // impossible
        Console.WriteLine(SolveNQueens(6).Count);
        Console.WriteLine(SolveNQueens(8).Count);   // the classic answer
    }
}
```

