```

**Logic**

Each digit maps to three or four letters, so the result is the Cartesian product of those sets: for a d-digit input there are roughly 3^d to 4^d combinations. Backtracking builds them one character at a time, recursing at each digit and undoing afterwards.

The only real edge case is the empty input, which should produce an empty list rather than a list containing one empty string, since there are no combinations of no digits.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    private static readonly Dictionary<char, string> Keys = new()
    {
        ['2'] = "abc", ['3'] = "def", ['4'] = "ghi", ['5'] = "jkl",
        ['6'] = "mno", ['7'] = "pqrs", ['8'] = "tuv", ['9'] = "wxyz",
    };

    public static IList<string> LetterCombinations(string digits)
    {
        var result = new List<string>();

        // No digits means no combinations, not one empty combination.
        if (string.IsNullOrEmpty(digits)) return result;

        Backtrack(digits, 0, new StringBuilder(), result);
        return result;
    }

    private static void Backtrack(string digits, int index, StringBuilder current, IList<string> result)
    {
        if (index == digits.Length)
        {
            result.Add(current.ToString());
            return;
        }

        if (!Keys.TryGetValue(digits[index], out string letters))
        {
            Backtrack(digits, index + 1, current, result);   // ignore 0, 1 and anything odd
            return;
        }

        foreach (char c in letters)
        {
            current.Append(c);
            Backtrack(digits, index + 1, current, result);
            current.Length--;                                 // undo the append
        }
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(",", LetterCombinations("23")));
        Console.WriteLine(string.Join(",", LetterCombinations("2")));
        Console.WriteLine(LetterCombinations("").Count);
        Console.WriteLine(string.Join(",", LetterCombinations("7")));
        Console.WriteLine(LetterCombinations("234").Count);
        Console.WriteLine(LetterCombinations("79").Count);      // 4 x 4
    }
}
```

