**Logic**

Build the string one character at a time, tracking how many open and close brackets have been placed. Two rules keep every partial string valid, so no invalid candidate is ever generated: you may add an open bracket while fewer than n have been used, and a close bracket only while it would not exceed the open count.

That pruning is the point. Generating all 2^(2n) strings and filtering the valid ones works but explores vastly more; the constrained version visits only the Catalan number of results, which for n = 3 is 5 rather than 64.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution
{
    public static IList<string> GenerateParenthesis(int n)
    {
        var result = new List<string>();
        if (n <= 0) return result;

        Backtrack(n, 0, 0, new StringBuilder(), result);
        return result;
    }

    private static void Backtrack(int n, int open, int close, StringBuilder current, IList<string> result)
    {
        if (current.Length == n * 2)
        {
            result.Add(current.ToString());
            return;
        }

        // Open a bracket while any remain.
        if (open < n)
        {
            current.Append('(');
            Backtrack(n, open + 1, close, current, result);
            current.Length--;
        }

        // Close one only if it would not outnumber the opens: that is what keeps
        // every prefix valid and prunes the invalid half of the tree.
        if (close < open)
        {
            current.Append(')');
            Backtrack(n, open, close + 1, current, result);
            current.Length--;
        }
    }

    public static void Main()
    {
        Console.WriteLine(string.Join(" ", GenerateParenthesis(3)));
        Console.WriteLine(string.Join(" ", GenerateParenthesis(1)));
        Console.WriteLine(string.Join(" ", GenerateParenthesis(2)));
        Console.WriteLine(GenerateParenthesis(0).Count);
        Console.WriteLine(GenerateParenthesis(4).Count);    // Catalan(4)
        Console.WriteLine(GenerateParenthesis(5).Count);    // Catalan(5)
    }
}
```

