**Logic**

Depth-first search from every cell whose letter matches the word's first character. At each step try the four neighbours for the next character, marking the current cell as in-use so a single path cannot reuse it, then unmarking on the way out.

That mark-and-restore is the difference between this and a flood fill: the restriction is per path, not global, because a cell excluded from one path must still be available to another. Worst case O(rows · cols · 4^L) for a word of length L.

**Program**

```csharp
using System;

public class Solution
{
    public static bool Exist(char[][] board, string word)
    {
        if (board == null || board.Length == 0 || string.IsNullOrEmpty(word)) return false;

        for (int r = 0; r < board.Length; r++)
            for (int c = 0; c < board[0].Length; c++)
                if (Search(board, word, r, c, 0)) return true;

        return false;
    }

    private static bool Search(char[][] board, string word, int r, int c, int index)
    {
        if (index == word.Length) return true;

        if (r < 0 || r >= board.Length || c < 0 || c >= board[0].Length) return false;
        if (board[r][c] != word[index]) return false;

        char original = board[r][c];
        board[r][c] = '\0';        // in use on THIS path only

        bool found = Search(board, word, r - 1, c, index + 1)
                  || Search(board, word, r + 1, c, index + 1)
                  || Search(board, word, r, c - 1, index + 1)
                  || Search(board, word, r, c + 1, index + 1);

        board[r][c] = original;    // restore, so other paths may still use it

        return found;
    }

    private static char[][] Parse(params string[] rows)
    {
        var g = new char[rows.Length][];
        for (int i = 0; i < rows.Length; i++) g[i] = rows[i].ToCharArray();
        return g;
    }

    public static void Main()
    {
        var board = Parse("ABCE", "SFCS", "ADEE");

        Console.WriteLine(Exist(board, "ABCCED"));
        Console.WriteLine(Exist(board, "SEE"));
        Console.WriteLine(Exist(board, "ABCB"));    // would need to reuse the B
        Console.WriteLine(Exist(board, "A"));
        Console.WriteLine(Exist(board, "Z"));
        Console.WriteLine(Exist(Parse("AB"), "BA"));
    }
}
```

