**Logic**

Halve the search range each step. Compare the middle element to the target: equal means found, smaller means discard the left half, larger means discard the right half. O(log n) time, O(1) space.

Two details cause almost every binary-search bug. First, compute the midpoint as `low + (high - low) / 2` rather than `(low + high) / 2`, since the latter overflows when both indices are large. Second, be consistent about whether `high` is inclusive; here it is, so the loop condition is `low <= high` and the halves move to `mid + 1` and `mid - 1`.

**Program**

```csharp
using System;

public class Solution
{
    public static int Search(int[] nums, int target)
    {
        if (nums == null || nums.Length == 0) return -1;

        int low = 0, high = nums.Length - 1;    // high is inclusive

        while (low <= high)
        {
            int mid = low + (high - low) / 2;   // overflow-safe midpoint

            if (nums[mid] == target) return mid;
            if (nums[mid] < target) low = mid + 1;
            else high = mid - 1;
        }

        return -1;
    }

    // Leftmost insertion point: where target would go to keep the array sorted.
    // This is the form that generalises to first/last occurrence problems.
    public static int LowerBound(int[] nums, int target)
    {
        int low = 0, high = nums.Length;        // high is exclusive here
        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (nums[mid] < target) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    public static void Main()
    {
        int[] nums = { -1, 0, 3, 5, 9, 12 };

        Console.WriteLine(Search(nums, 9));
        Console.WriteLine(Search(nums, 2));
        Console.WriteLine(Search(nums, -1));     // first element
        Console.WriteLine(Search(nums, 12));     // last element
        Console.WriteLine(Search(new int[0], 1));

        Console.WriteLine(LowerBound(nums, 4));  // would insert at index 3
        Console.WriteLine(LowerBound(nums, 13)); // past the end
    }
}
```

