**Logic**

Two quite different problems share this name, and the right answer depends on which.

If each row is sorted and every row starts after the previous row ends, the matrix is really one sorted array folded into a grid, so a single binary search over the virtual index works, with row and column recovered by division and remainder. That is O(log(rows·cols)).

If only rows and columns are individually sorted, with no relationship between them, start at the top-right corner: moving left decreases the value, moving down increases it, so each comparison eliminates a whole row or column. That is O(rows + cols).

**Program**

```csharp
using System;

public class Solution
{
    // Fully sorted when flattened: one binary search over the virtual index.
    public static bool SearchFlattened(int[][] matrix, int target)
    {
        if (matrix == null || matrix.Length == 0) return false;

        int rows = matrix.Length, cols = matrix[0].Length;
        int low = 0, high = rows * cols - 1;

        while (low <= high)
        {
            int mid = low + (high - low) / 2;
            int value = matrix[mid / cols][mid % cols];   // unfold the index

            if (value == target) return true;
            if (value < target) low = mid + 1;
            else high = mid - 1;
        }

        return false;
    }

    // Rows and columns sorted independently: staircase from the top-right.
    public static bool SearchStaircase(int[][] matrix, int target)
    {
        if (matrix == null || matrix.Length == 0) return false;

        int row = 0, col = matrix[0].Length - 1;

        while (row < matrix.Length && col >= 0)
        {
            int value = matrix[row][col];

            if (value == target) return true;
            if (value > target) col--;    // everything below in this column is larger
            else row++;                   // everything left in this row is smaller
        }

        return false;
    }

    public static void Main()
    {
        var sorted = new[] {
            new[] { 1, 3, 5, 7 },
            new[] { 10, 11, 16, 20 },
            new[] { 23, 30, 34, 60 } };

        Console.WriteLine(SearchFlattened(sorted, 3));
        Console.WriteLine(SearchFlattened(sorted, 13));
        Console.WriteLine(SearchStaircase(sorted, 60));

        var staircase = new[] {
            new[] { 1, 4, 7, 11 },
            new[] { 2, 5, 8, 12 },
            new[] { 3, 6, 9, 16 } };

        Console.WriteLine(SearchStaircase(staircase, 5));
        Console.WriteLine(SearchStaircase(staircase, 10));
        Console.WriteLine(SearchStaircase(new[] { new[] { 1 } }, 1));
    }
}
