**Logic**

Binary search comparing the midpoint against the *right* end rather than the left. If the middle element is greater than the rightmost, the rotation point lies to the right, so the minimum is after the midpoint. Otherwise the midpoint could itself be the minimum, so the right bound moves to the midpoint without excluding it.

Comparing against the left end instead does not work cleanly, because an unrotated array would then look identical to one rotated fully. O(log n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int FindMin(int[] nums)
    {
        if (nums == null || nums.Length == 0) throw new ArgumentException("empty");

        int low = 0, high = nums.Length - 1;

        while (low < high)
        {
            int mid = low + (high - low) / 2;

            // Compare with the RIGHT end: an unrotated array behaves correctly.
            if (nums[mid] > nums[high]) low = mid + 1;   // minimum is strictly right
            else high = mid;                             // mid might BE the minimum
        }

        return nums[low];
    }

    // With duplicates the worst case degrades to O(n) and cannot be improved.
    public static int FindMinWithDuplicates(int[] nums)
    {
        int low = 0, high = nums.Length - 1;

        while (low < high)
        {
            int mid = low + (high - low) / 2;

            if (nums[mid] > nums[high]) low = mid + 1;
            else if (nums[mid] < nums[high]) high = mid;
            else high--;        // cannot tell which side: shrink by one
        }

        return nums[low];
    }

    public static void Main()
    {
        Console.WriteLine(FindMin(new[] { 3, 4, 5, 1, 2 }));
        Console.WriteLine(FindMin(new[] { 4, 5, 6, 7, 0, 1, 2 }));
        Console.WriteLine(FindMin(new[] { 11, 13, 15, 17 }));      // not rotated
        Console.WriteLine(FindMin(new[] { 2, 1 }));
        Console.WriteLine(FindMin(new[] { 5 }));
        Console.WriteLine(FindMinWithDuplicates(new[] { 2, 2, 2, 0, 1 }));
    }
}
