**Logic**

Binary search the answer between 1 and n/2, testing whether a candidate squared exceeds the target. It is the simplest instance of binary search on the answer: feasibility is monotonic, since if k² ≤ n then every smaller value also satisfies it.

The trap is overflow. Computing `mid * mid` in an int overflows for mid above about 46,341, wrapping negative and breaking the comparison. Either accumulate in a long or, better, compare `mid` against `n / mid` to avoid multiplication entirely.

O(log n) time, O(1) space.

**Program**

```csharp
using System;

public class Solution
{
    public static int MySqrt(int n)
    {
        if (n < 0) throw new ArgumentOutOfRangeException(nameof(n));
        if (n < 2) return n;                 // 0 and 1 are their own roots

        int low = 1, high = n / 2;           // the root of n >= 2 never exceeds n/2

        while (low <= high)
        {
            int mid = low + (high - low) / 2;

            // Division rather than mid * mid: no overflow, no long needed.
            int quotient = n / mid;

            if (quotient == mid) return mid;          // exact root
            if (quotient > mid) low = mid + 1;        // mid is too small
            else high = mid - 1;
        }

        return high;    // the floor of the true root
    }

    // Newton's method: converges quadratically, far fewer iterations for large n.
    public static int MySqrtNewton(int n)
    {
        if (n < 2) return n;

        long guess = n;
        while (guess * guess > n) guess = (guess + n / guess) / 2;

        return (int)guess;
    }

    public static void Main()
    {
        Console.WriteLine(MySqrt(4));
        Console.WriteLine(MySqrt(8));            // floor of 2.828
        Console.WriteLine(MySqrt(0));
        Console.WriteLine(MySqrt(1));
        Console.WriteLine(MySqrt(2147395599));   // large: would overflow mid * mid
        Console.WriteLine(MySqrtNewton(2147395599));
    }
}
