**Logic**

Pick a pivot, partition the array so that smaller elements sit left of it and larger ones right, then recurse on both sides. The pivot lands in its final position after each partition, so no merge step is needed.

Average O(n log n), but O(n²) when partitions are badly unbalanced, which a deterministic pivot on sorted input guarantees. Randomising the pivot makes that case vanishingly unlikely. Recursing into the smaller side first and looping on the larger bounds the stack at O(log n).

Quicksort is not stable, which is why .NET's `Array.Sort` uses introsort and `OrderBy` uses a stable merge sort.

**Program**

```csharp
using System;

public class Solution
{
    private static readonly Random Rng = new(42);   // fixed seed: reproducible output

    public static void QuickSort(int[] nums) => Sort(nums, 0, nums.Length - 1);

    private static void Sort(int[] nums, int low, int high)
    {
        // Loop rather than recurse on the larger side: stack stays O(log n).
        while (low < high)
        {
            int p = Partition(nums, low, high);

            if (p - low < high - p)
            {
                Sort(nums, low, p - 1);
                low = p + 1;
            }
            else
            {
                Sort(nums, p + 1, high);
                high = p - 1;
            }
        }
    }

    private static int Partition(int[] nums, int low, int high)
    {
        // Random pivot: defends against the sorted-input worst case.
        int pivotIndex = low + Rng.Next(high - low + 1);
        (nums[pivotIndex], nums[high]) = (nums[high], nums[pivotIndex]);

        int pivot = nums[high];
        int store = low;

        for (int i = low; i < high; i++)
            if (nums[i] < pivot)
                (nums[store], nums[i]) = (nums[i], nums[store++]);

        (nums[high], nums[store]) = (nums[store], nums[high]);
        return store;
    }

    private static string Sorted(int[] a)
    {
        var copy = (int[])a.Clone();
        QuickSort(copy);
        return string.Join(",", copy);
    }

    public static void Main()
    {
        Console.WriteLine(Sorted(new[] { 5, 2, 9, 1, 5, 6 }));
        Console.WriteLine(Sorted(new[] { 1, 2, 3, 4, 5 }));      // already sorted
        Console.WriteLine(Sorted(new[] { 5, 4, 3, 2, 1 }));      // reversed
        Console.WriteLine(Sorted(new[] { 7, 7, 7, 7 }));         // all equal
        Console.WriteLine(Sorted(new[] { 42 }));
        Console.WriteLine(Sorted(new int[0]));
    }
}
```

