1,1,2,2
42

```

**Logic**

Quicksort that recurses into only one side. After partitioning, the pivot sits at its final index; if that index is the target rank you are done, otherwise the answer lies entirely on one side and the other can be discarded.

Discarding half the work each time gives the average recurrence T(n) = T(n/2) + O(n), which sums to O(n) rather than O(n log n). The worst case is still O(n²) with a bad pivot, which randomisation makes negligible.

**Program**

```csharp
using System;

public class Solution
{
    private static readonly Random Rng = new(7);

    // k is 1-based: k = 1 returns the smallest element.
    public static int KthSmallest(int[] nums, int k)
    {
        if (nums == null || k < 1 || k > nums.Length)
            throw new ArgumentOutOfRangeException(nameof(k));

        var a = (int[])nums.Clone();     // do not reorder the caller's array
        int target = k - 1;
        int low = 0, high = a.Length - 1;

        while (true)
        {
            if (low == high) return a[low];

            int p = Partition(a, low, high);

            if (p == target) return a[p];
            if (p < target) low = p + 1;   // answer is to the right
            else high = p - 1;             // answer is to the left
        }
    }

    private static int Partition(int[] a, int low, int high)
    {
        int pivotIndex = low + Rng.Next(high - low + 1);
        (a[pivotIndex], a[high]) = (a[high], a[pivotIndex]);

        int pivot = a[high], store = low;

        for (int i = low; i < high; i++)
            if (a[i] < pivot)
                (a[store], a[i]) = (a[i], a[store++]);

        (a[high], a[store]) = (a[store], a[high]);
        return store;
    }

    public static void Main()
    {
        int[] a = { 7, 10, 4, 3, 20, 15 };

        Console.WriteLine(KthSmallest(a, 1));
        Console.WriteLine(KthSmallest(a, 3));
        Console.WriteLine(KthSmallest(a, 6));
        Console.WriteLine(string.Join(",", a));       // the input is untouched
        Console.WriteLine(KthSmallest(new[] { 5 }, 1));
        Console.WriteLine(KthSmallest(new[] { 2, 2, 2 }, 2));
    }
}
