**Logic**

An inversion is a pair where a larger value appears before a smaller one. Counting them naively is O(n²); merge sort counts them in O(n log n) as a side effect of merging.

During a merge, when an element from the right half is taken before elements remain in the left half, that element is smaller than every one of those remaining left elements, so all of those pairs are inversions and can be counted in one go rather than individually. Summing that across every merge gives the total.

**Program**

```csharp
using System;

public class Solution
{
    public static long CountInversions(int[] nums)
    {
        if (nums == null || nums.Length < 2) return 0;

        var work = (int[])nums.Clone();      // do not disturb the caller's array
        var buffer = new int[work.Length];
        return Sort(work, buffer, 0, work.Length - 1);
    }

    private static long Sort(int[] a, int[] buffer, int low, int high)
    {
        if (low >= high) return 0;

        int mid = low + (high - low) / 2;
        long count = Sort(a, buffer, low, mid) + Sort(a, buffer, mid + 1, high);

        return count + Merge(a, buffer, low, mid, high);
    }

    private static long Merge(int[] a, int[] buffer, int low, int mid, int high)
    {
        Array.Copy(a, low, buffer, low, high - low + 1);

        long inversions = 0;
        int i = low, j = mid + 1;

        for (int k = low; k <= high; k++)
        {
            if (i > mid) a[k] = buffer[j++];
            else if (j > high) a[k] = buffer[i++];
            else if (buffer[j] < buffer[i])
            {
                // buffer[j] is smaller than every remaining element of the left
                // half, so that whole block forms inversions with it at once.
                inversions += mid - i + 1;
                a[k] = buffer[j++];
            }
            else a[k] = buffer[i++];
        }

        return inversions;
    }

    public static void Main()
    {
        Console.WriteLine(CountInversions(new[] { 2, 4, 1, 3, 5 }));   // (2,1) (4,1) (4,3)
        Console.WriteLine(CountInversions(new[] { 1, 2, 3, 4, 5 }));   // sorted: none
        Console.WriteLine(CountInversions(new[] { 5, 4, 3, 2, 1 }));   // reversed: n(n-1)/2
        Console.WriteLine(CountInversions(new[] { 1, 1, 1 }));         // equal: not inversions
        Console.WriteLine(CountInversions(new[] { 7 }));

        var original = new[] { 3, 1, 2 };
        CountInversions(original);
        Console.WriteLine(string.Join(",", original));                 // untouched
    }
}
